window.MG_LAZY_DATA["data/lazy/owner-courses/b301-62a2c30a7cda657b.json"]={sha256:"62a2c30a7cda657b9c3622c7663196a0b1e9895db09ad09c2461a2e9d367271b",value:{"id":"b301","category":"rail","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"languageCoverage":["zh-TW","en"],"sourceIds":["v6-thsr-discovery","v6-thsr-route-safety","v6-thsr-disaster","v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"stages":[{"id":"b301-stage01","order":1,"steps":[{"id":"b301-v6-01","sequence":1,"order":1,"sourceIds":["v6-thsr-discovery","v6-thsr-route-safety"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":[],"title":"建立高鐵系統邊界","titleEn":"Map high-speed-rail system boundaries","objective":"分開土建、軌道、供電、車輛、控制及營運介面。","objectiveEn":"Separate civil, track, power, vehicle, control and operations interfaces.","instruction":"畫出土建承托軌道、軌道導引車輛的主鏈，再加供電與控制連到車輛。以不同箭頭表示力、能量與資訊，為每種介面列一項驗證問題。","instructionEn":"Draw civil support to track to vehicle, then connect power and control to the vehicle. Use distinct arrows for force, energy and information, with one verification question per interface.","observation":"觀察車輛能運轉是否仍不足以證明軌道與控制整合已完成。","observationEn":"Recognize that a moving train alone does not establish completed track and control integration.","failure":"把高鐵等同於一列高速列車，省略路線與控制條件。","failureEn":"Equating a high-speed railway with a fast train while omitting route and control conditions.","check":"六個子系統都有介面，且箭頭的物理意義清楚。","checkEn":"Connect all six subsystems and explain the physical meaning of each arrow.","knowledge":[{"id":"b301-v6-01-k1","title":"跨專業系統","titleEn":"Multidiscipline system","text":"高速運行取決於車輛與路線、供電、控制及營運的一致性。","textEn":"High-speed operation depends on compatibility among vehicles, route, power, control and operations."},{"id":"b301-v6-01-k2","title":"不同傳遞量","titleEn":"Different transferred quantities","text":"力、電能與控制資訊需要不同驗證，不能用同一箭頭含糊表示。","textEn":"Force, electrical energy and control information require different verification and should not share an ambiguous arrow."}],"quiz":{"options":["與路線動態及控制系統相容","列車靜態寬度已被量測","尺寸文件有可比對的幾何內容"],"optionsEn":["Compatibility with route dynamics and control","That static train width was measured","That the dimensional record contains comparable geometry"],"answer":0,"question":"列車靜態尺寸合格，還不能單獨證明哪件事？","questionEn":"A train meets static dimensional requirements. What does that not establish by itself?","explanation":"靜態幾何只是整合條件的一部分，仍需動態與控制證據。","explanationEn":"Static geometry is only part of integration; dynamic and control evidence remains necessary."}},{"id":"b301-v6-02","sequence":2,"order":2,"sourceIds":["v6-thsr-discovery"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b301-v6-01"],"title":"比較曲線與行車需求","titleEn":"Compare alignment curves and service needs","objective":"理解速度、曲線與舒適性的相互約束。","objectiveEn":"Understand relationships among speed, curvature and ride requirements.","instruction":"自繪直線、緩和曲線與圓曲線的概念路線，標出方向變化。比較兩種示意速度下需要關注的橫向反應，不指定實線設計半徑或超高。","instructionEn":"Sketch straight, transition and circular alignment sections, marking direction changes. Compare lateral-response concerns at two illustrative speeds without assigning real design radius or cant.","observation":"觀察平面方向平順，是否仍有垂向坡度或接續問題。","observationEn":"Check whether a smooth plan alignment still leaves vertical-gradient or transition issues.","failure":"只看列車最高速度，就認定所有曲線都能以同速通過。","failureEn":"Assuming every curve supports a train’s maximum rated speed.","check":"交付平面及縱向問題各一項，說明缺少的驗證資料。","checkEn":"Provide one plan and one vertical-profile question with missing verification data.","knowledge":[{"id":"b301-v6-02-k1","title":"速度與曲率","titleEn":"Speed and curvature","text":"橫向運動反應取決於速度與曲率的組合，而非車輛標稱速度。","textEn":"Lateral motion depends on the combination of speed and curvature, not the vehicle’s rated speed alone."},{"id":"b301-v6-02-k2","title":"平順接續","titleEn":"Smooth transitions","text":"方向或坡度變化需要連續性考量，不能只把直線片段接起來。","textEn":"Direction and gradient changes require continuity considerations rather than simply joining straight segments."}],"quiz":{"options":["車輛靜態長度是否自行縮短","橫向動態反應與舒適性如何改變","既有曲線的幾何是否因速度而自動改變"],"optionsEn":["Whether static vehicle length automatically shortens","How lateral response and comfort change","Whether curve geometry automatically changes with speed"],"answer":1,"question":"同一曲線提高示意速度時，最合理的研究問題是什麼？","questionEn":"If illustrative speed increases on the same curve, which question is most relevant?","explanation":"速度變動改變動態需求；不能假定幾何或車輛尺寸會自行補償。","explanationEn":"Changing speed alters dynamic demands; geometry and vehicle dimensions do not automatically compensate."}},{"id":"b301-v6-03","sequence":3,"order":3,"sourceIds":["v6-thsr-disaster"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b301-v6-02"],"title":"追蹤地層下陷到軌道","titleEn":"Trace subsidence to track geometry","objective":"分辨均勻沉降與差異沉降的介面影響。","objectiveEn":"Distinguish interface effects of uniform and differential settlement.","instruction":"用同一條示意軌道畫均勻下降與局部下降兩種剖面。將地面觀測、橋墩位移與軌道高低資料列成三層，說明不能互相替代的理由。","instructionEn":"Draw uniform and localized settlement beneath the same illustrative track. Separate ground observations, pier movement and track levels into three evidence layers and explain their limits.","observation":"比較總沉降相近的兩例，局部坡折是否不同。","observationEn":"Compare local gradient changes in examples with similar total settlement.","failure":"以沿線平均沉降值代表所有局部軌道變化。","failureEn":"Using average line-wide settlement to represent every local track change.","check":"指出最需補充局部量測的位置，並維持共同高程基準。","checkEn":"Identify locations needing local measurements and retain a common elevation datum.","knowledge":[{"id":"b301-v6-03-k1","title":"差異變形","titleEn":"Differential movement","text":"鄰近支承的相對變形會影響幾何連續性，不能只看平均值。","textEn":"Relative movement of neighboring supports affects geometric continuity and is not captured by an average."},{"id":"b301-v6-03-k2","title":"跨層證據","titleEn":"Evidence across levels","text":"地盤、土建與軌道的反應需對齊位置和時間才可比較。","textEn":"Ground, civil and track responses must share location and time references to be compared."}],"quiz":{"options":["所有支承一起均勻下降的一段必定較差","僅憑總沉降即可判定兩者完全相同","沉降集中在短距離內的一段"],"optionsEn":["The uniformly settling section must be worse","Total settlement alone proves the sections identical","The section where settlement is concentrated over a short distance"],"answer":2,"question":"兩段總沉降相同，哪段仍可能有較大的幾何變化？","questionEn":"Two sections have equal total settlement. Which may still have greater geometric change?","explanation":"沉降的空間分布會改變坡度與曲率，即使總量相同。","explanationEn":"Spatial distribution changes slope and curvature even when total settlement is equal."}},{"id":"b301-v6-04","sequence":4,"order":4,"sourceIds":["v6-thsr-discovery","v6-thsr-disaster"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b301-v6-03"],"title":"檢查橋梁與軌道支承介面","titleEn":"Review bridge–track support interfaces","objective":"把預鑄構件交接連到軌道幾何基準。","objectiveEn":"Connect precast-member handover to track-geometry references.","instruction":"以自繪高架橋分開橋墩、支承、梁體與軌道層，標出縱向伸縮和量測基準。列出梁體就位後，軌道專業仍需取得的幾何與狀態資料。","instructionEn":"Separate piers, bearings, girders and track layers in a viaduct sketch. Mark longitudinal movement and survey references; list geometry and state records needed by the track team after girder placement.","observation":"注意梁體就位合格不等於軌道精度與長期位移已被驗證。","observationEn":"Accepted girder placement does not establish track precision or long-term movement behavior.","failure":"將橋梁竣工標高直接當成最終鋼軌標高，忽略中間構造。","failureEn":"Treating bridge as-built level as final rail level while omitting intermediate layers.","check":"完成土建到軌道的介面表，至少含基準、可動方向與待補資料。","checkEn":"Complete a civil-to-track interface sheet including reference, movement direction and missing records.","knowledge":[{"id":"b301-v6-04-k1","title":"層間累積","titleEn":"Layer accumulation","text":"各層厚度、調整與變形共同決定鋼軌最終幾何。","textEn":"Layer thickness, adjustment and deformation together determine final rail geometry."},{"id":"b301-v6-04-k2","title":"可動支承","titleEn":"Movable supports","text":"設計允許的伸縮與需要限制的位移，應在模型中分清。","textEn":"Intended movement and movement that must be restrained should be distinguished in the model."}],"quiz":{"options":["中間層與調整量共同決定軌面位置","梁頂標高與軌面必定相同","軌道幾何與土建從不互相影響"],"optionsEn":["Intermediate layers and adjustments determine rail position","Girder-top and rail elevations are necessarily identical","Track geometry and civil works never interact"],"answer":0,"question":"梁頂標高正確，為何還需軌道層交接資料？","questionEn":"Why are track-layer records needed even if girder-top elevation is correct?","explanation":"交接要追蹤完整尺寸鏈，而不是只驗證其中一層。","explanationEn":"Handover must trace the full dimensional chain, not only one layer."}}],"title":"路線與土建介面","titleEn":"Alignment and civil interfaces","description":"將路線幾何、地盤與橋梁條件連到軌道需求。","descriptionEn":"Connect alignment, ground and bridge conditions to track requirements."},{"id":"b301-stage02","order":2,"steps":[{"id":"b301-v6-05","sequence":5,"order":1,"sourceIds":["v6-thsr-discovery"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b301-v6-04"],"title":"比較軌道形式及轉換區","titleEn":"Compare track forms and transition zones","objective":"理解不同軌道形式回應不同介面要求。","objectiveEn":"Understand how track forms respond to different interface needs.","instruction":"依探索館說明，整理版式軌道、道岔附近的配置和低振動軌道三種功能重點。畫兩種剛度不同的軌道相接，列出需量測的幾何與動態反應。","instructionEn":"Using the museum overview, compare slab-track, turnout-area and low-vibration functions. Sketch a transition between track forms of different stiffness and identify geometric and dynamic observations.","observation":"觀察靜態軌面平順是否仍可能有支承剛度變化。","observationEn":"Recognize that a smooth static rail profile can still cross a stiffness change.","failure":"把全線軌道假定為單一材料與單一剛度。","failureEn":"Assuming one material and stiffness for the entire line.","check":"比較表須有功能、支承差異及轉換區待驗證事項。","checkEn":"Include purpose, support differences and transition-zone verification needs.","knowledge":[{"id":"b301-v6-05-k1","title":"功能選型","titleEn":"Function-led selection","text":"道岔定位、一般正線與振動控制可能需要不同構造組合。","textEn":"Turnout positioning, ordinary main line and vibration control can require different structural arrangements."},{"id":"b301-v6-05-k2","title":"過渡反應","titleEn":"Transition response","text":"支承特性突變可影響輪軌互動，需與幾何一起檢查。","textEn":"Abrupt support-property changes can affect wheel–rail interaction and should be examined with geometry."}],"quiz":{"options":["有，軌頂相同即代表剛度相同","沒有，支承特性與動態反應仍需證據","只要列車靜止不晃就已足夠"],"optionsEn":["Yes; equal rail elevation means equal stiffness","No; support properties and dynamic response still need evidence","A stationary train not rocking is sufficient"],"answer":1,"question":"兩段軌頂高程相同，是否已證明轉換區動態相容？","questionEn":"Two sections have equal rail elevation. Does that prove dynamic compatibility at the transition?","explanation":"高程只描述幾何的一部分，無法取代動態介面檢核。","explanationEn":"Elevation describes only part of geometry and does not replace dynamic interface review."}},{"id":"b301-v6-06","sequence":6,"order":2,"sourceIds":["v6-thsr-discovery","v6-thsr-route-safety"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b301-v6-05"],"title":"分開道岔位置與路線確認","titleEn":"Separate turnout position from route confirmation","objective":"辨識機械位置、位置證據與通行授權。","objectiveEn":"Distinguish mechanical position, position evidence and movement authority.","instruction":"畫一個簡化分岔軌道，用不同符號表示移動部件、位置回報和控制狀態。寫出「位置未知」的桌上案例，說明為何不能只看遠景照片決定路線。","instructionEn":"Sketch a turnout with separate symbols for moving components, position indication and control state. Describe an unknown-position tabletop case and why a distant photograph cannot establish a route.","observation":"觀察部件看似靠妥與完整位置證據是否為不同層次。","observationEn":"Distinguish apparent mechanical closure from complete position evidence.","failure":"將目視位置直接等同於系統已確認且允許列車通行。","failureEn":"Equating visual position with system confirmation and authority to move.","check":"表格保留機械、檢知、控制三欄，未知狀態不得寫成已驗證。","checkEn":"Keep mechanical, detection and control columns separate; do not relabel unknown states as verified.","knowledge":[{"id":"b301-v6-06-k1","title":"證據鏈","titleEn":"Evidence chain","text":"幾何位置、檢知資訊和系統授權屬於不同介面。","textEn":"Physical position, detection information and system authority are different interfaces."},{"id":"b301-v6-06-k2","title":"未知狀態","titleEn":"Unknown state","text":"資料不足不是正常的同義詞，應保留為待查證。","textEn":"Insufficient information is not equivalent to normal operation and must remain unresolved."}],"quiz":{"options":["外觀可替代全部系統證據","可直接推論控制授權已成立","機械觀察已記錄，系統位置仍未驗證"],"optionsEn":["Appearance replaces all system evidence","Movement authority can be inferred directly","Mechanical observation recorded; system position unverified"],"answer":2,"question":"道岔外觀位置正確但位置回報未確認，最合適的課程記錄是什麼？","questionEn":"A turnout looks aligned but its position indication is unconfirmed. What is the best learning record?","explanation":"不同證據欄位不能互相冒充，未知應清楚留下。","explanationEn":"Different evidence fields are not interchangeable; unknowns must remain visible."}},{"id":"b301-v6-07","sequence":7,"order":3,"sourceIds":["v6-thsr-discovery"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b301-v6-06"],"title":"建立集電與供電介面圖","titleEn":"Map current-collection and power interfaces","objective":"分辨供電存在與受電弓接觸品質。","objectiveEn":"Distinguish supply availability from pantograph contact quality.","instruction":"自繪變電、電車線、受電弓與車輛用電鏈，另加接觸幾何示意。以「有電但接觸不穩」假想例子列出電氣與機械兩類證據，不提供接近帶電設備的作業。","instructionEn":"Sketch supply, catenary, pantograph and vehicle demand, adding contact geometry. For an invented energized-but-unstable-contact case, list electrical and mechanical evidence without field work near live equipment.","observation":"比較上游供電量測與車上集電狀態能回答的不同問題。","observationEn":"Compare the questions answered by upstream supply readings and onboard collection observations.","failure":"看到上游電壓正常就排除所有集電介面問題。","failureEn":"Ruling out every collection-interface problem because upstream voltage is normal.","check":"每一個假說須連到電氣或機械證據，並註明位置與時間。","checkEn":"Link each hypothesis to electrical or mechanical evidence with location and time.","knowledge":[{"id":"b301-v6-07-k1","title":"機電接觸","titleEn":"Electromechanical contact","text":"集電同時是電能傳遞與運動接觸問題。","textEn":"Current collection involves both electrical transfer and moving mechanical contact."},{"id":"b301-v6-07-k2","title":"觀測位置","titleEn":"Observation location","text":"不同測點位於不同系統邊界，不能隨意互相替代。","textEn":"Measurements at different system boundaries cannot be substituted indiscriminately."}],"quiz":{"options":["該測點電壓在觀察期間穩定","受電弓全程接觸品質必定良好","所有車上負載均無異常"],"optionsEn":["Voltage at that location was stable during observation","Pantograph contact was necessarily good throughout","Every onboard load was fault-free"],"answer":0,"question":"上游電壓穩定能直接證明哪項？","questionEn":"What does stable upstream voltage directly establish?","explanation":"測量只能先支持其所在邊界與時間範圍內的結論。","explanationEn":"A measurement initially supports conclusions within its own location and time boundary."}},{"id":"b301-v6-08","sequence":8,"order":4,"sourceIds":["v6-thsr-route-safety"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b301-v6-07"],"title":"理解ATC速度防護證據","titleEn":"Interpret ATC speed-protection evidence","objective":"區分行車計畫、允許速度與實際速度。","objectiveEn":"Distinguish timetable intent, permitted speed and actual speed.","instruction":"自繪三條明確標成假想的曲線：計畫速度、允許速度、實際速度。找出實際速度接近或超出允許範圍的區域，說明需要防護而非只調整時刻表。","instructionEn":"Sketch explicitly fictional planned, permitted and actual speed curves. Identify where actual speed approaches or exceeds permission and explain the need for protection rather than merely changing the timetable.","observation":"觀察晚點與違反速度限制是不同問題。","observationEn":"Distinguish lateness from violation of a speed limit.","failure":"因列車晚點就把時刻表目標速度當成可突破的安全限制。","failureEn":"Treating a timetable target as permission to exceed a safety limit because the train is late.","check":"標示三種曲線的來源角色與一個資料不足的區段。","checkEn":"Identify the role behind each curve and one section with insufficient information.","knowledge":[{"id":"b301-v6-08-k1","title":"控制約束","titleEn":"Control constraints","text":"允許速度受前方路線與行車條件影響，不只取決於車輛能力。","textEn":"Permitted speed depends on route and traffic conditions, not only vehicle capability."},{"id":"b301-v6-08-k2","title":"安全與服務","titleEn":"Safety and service","text":"準點目標與防護約束不是同一層級的判斷。","textEn":"Punctuality objectives and protection constraints are different decision layers."}],"quiz":{"options":["計畫速度自動覆蓋允許速度","計畫需受當時允許範圍約束","只要實際速度低於車輛最高速度即可"],"optionsEn":["Planned speed automatically overrides permission","The plan remains constrained by current permission","Actual speed need only remain below vehicle maximum"],"answer":1,"question":"計畫速度高於當時允許速度，應如何解讀課程圖？","questionEn":"Planned speed exceeds current permitted speed. How should the diagram be interpreted?","explanation":"車輛能力與時刻表不能取代路線與行車防護條件。","explanationEn":"Vehicle capability and timetable goals do not replace route and traffic protection conditions."}}],"title":"軌道與機電整合","titleEn":"Track and electromechanical integration","description":"辨識軌道形式、道岔、集電與控制的不同證據。","descriptionEn":"Identify distinct evidence for track forms, turnouts, current collection and control."},{"id":"b301-stage03","order":3,"steps":[{"id":"b301-v6-09","sequence":9,"order":1,"sourceIds":["v6-thsr-disaster"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b301-v6-08"],"title":"配對災害與偵測位置","titleEn":"Match hazards to detector locations","objective":"說明不同災害需要不同觀察量與布設邏輯。","objectiveEn":"Explain why hazards require different observables and siting logic.","instruction":"自繪隧道口、跨河橋、邊坡及一般路段，將落石、水位、地滑、風與地震觀察配到合理區域。為每一配對補一句不能保證偵測所有事件的理由。","instructionEn":"Sketch a portal, river bridge, slope and ordinary section. Assign rockfall, water level, slope movement, wind and earthquake observations, noting one limitation for each.","observation":"觀察單一感測器位置能代表的空間範圍是否有限。","observationEn":"Consider the spatial limits of any one detector location.","failure":"認定只要全線裝有同一類感測器，就能覆蓋所有災害。","failureEn":"Assuming one detector type across the line covers every hazard.","check":"完成至少四個「災害—位置—觀察量—盲點」配對。","checkEn":"Complete at least four hazard–location–observable–blind-spot mappings.","knowledge":[{"id":"b301-v6-09-k1","title":"需求導向偵測","titleEn":"Hazard-led detection","text":"偵測器選擇與位置應回應特定事件如何影響路線。","textEn":"Detector type and location should respond to how a particular event affects the route."},{"id":"b301-v6-09-k2","title":"覆蓋限制","titleEn":"Coverage limits","text":"沒有告警可能是未發生，也可能是超出覆蓋或設備狀態問題。","textEn":"No alarm may mean no event, an event outside coverage, or a device-state problem."}],"quiz":{"options":["遠方車站的室內溫度","其他路段道岔的位置回報","相關河段的水位與流況"],"optionsEn":["Indoor temperature at a distant station","Turnout indication in another section","Water level and flow conditions in the relevant reach"],"answer":2,"question":"跨河橋的洪水風險，哪個觀察最直接相關？","questionEn":"Which observation is most directly relevant to flooding at a river bridge?","explanation":"觀察量需對應災害機制與位置；不相關的正常訊號不能替代。","explanationEn":"Observables must match hazard mechanism and location; unrelated normal readings are no substitute."}},{"id":"b301-v6-10","sequence":10,"order":2,"sourceIds":["v6-thsr-disaster"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b301-v6-09"],"title":"拆解地震後查證鏈","titleEn":"Decompose post-earthquake verification","objective":"區分告警、停止、檢查與恢復狀態。","objectiveEn":"Distinguish alarm, stop, inspection and restoration states.","instruction":"以紙上流程排列事件紀錄、影響區段、設施檢查、資料複核與授權交接。為每一節點寫出輸入證據與未完成時的標記，不填真實復駛速度或門檻。","instructionEn":"Arrange event records, affected sections, inspections, evidence review and authorization handover on paper. Name input evidence and incomplete-state labels without actual restart speeds or thresholds.","observation":"觀察地震訊號結束與設施已確認可用是否是不同時點。","observationEn":"Distinguish the end of shaking from confirmation that facilities are usable.","failure":"因感測器恢復正常，就省略受影響土建與軌道的查證。","failureEn":"Skipping civil and track checks because sensor readings have returned to normal.","check":"流程需顯示至少一個不能由感測器單獨證明的節點。","checkEn":"Show at least one stage that a sensor reading alone cannot verify.","knowledge":[{"id":"b301-v6-10-k1","title":"事件與狀態","titleEn":"Event versus condition","text":"告警描述事件或觀察；設施狀態仍需其他證據確認。","textEn":"An alarm describes an event or observation; facility condition requires additional evidence."},{"id":"b301-v6-10-k2","title":"分階段復核","titleEn":"Staged review","text":"停止、檢查與運行授權是不同責任，應各自留下紀錄。","textEn":"Stopping, inspection and operating authority are distinct responsibilities requiring records."}],"quiz":{"options":["不能，受影響設施與授權仍需查證","可以，事件結束等於設施無損","可以，只要列車沒有明顯外觀損傷"],"optionsEn":["No; affected facilities and authorization still require verification","Yes; an ended event means undamaged facilities","Yes, if trains show no visible damage"],"answer":0,"question":"地震波已停止，能否單憑此資訊判定全線可恢復？","questionEn":"Shaking has stopped. Does that alone establish line-wide readiness?","explanation":"事件停止不能證明每個結構、軌道與系統介面都仍符合要求。","explanationEn":"An ended event does not establish that every structure, track and system interface meets requirements."}},{"id":"b301-v6-11","sequence":11,"order":3,"sourceIds":["v6-thsr-discovery","v6-thsr-route-safety"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b301-v6-10"],"title":"管理維護與零件變更證據","titleEn":"Manage maintenance and component-change evidence","objective":"理解相容性需要超過外形與料號。","objectiveEn":"Understand why compatibility needs more than appearance and part numbers.","instruction":"自設一個更換感測器的紀錄，包含功能、接線介面、校正、版本與測試結果。比較新舊元件，在每個差異旁列出需更新的文件。","instructionEn":"Invent a sensor-replacement record with function, connection interface, calibration, version and test result. Compare old and new items, noting documents that each difference requires updating.","observation":"注意外形相同但量程、輸出定義或版本不同的情境。","observationEn":"Consider identical-looking parts with different ranges, output meanings or versions.","failure":"只因安裝孔位相同，就認定替代零件已完成相容驗證。","failureEn":"Declaring a replacement compatible solely because mounting holes match.","check":"交付功能差異表與可追溯的測試／文件清單。","checkEn":"Deliver a functional-difference table and a traceable test/document list.","knowledge":[{"id":"b301-v6-11-k1","title":"配置管理","titleEn":"Configuration management","text":"實際安裝狀態應與圖紙、設定及維護紀錄相符。","textEn":"Installed configuration should match drawings, settings and maintenance records."},{"id":"b301-v6-11-k2","title":"相容性驗證","titleEn":"Compatibility verification","text":"機械裝得上不代表電氣、資訊或功能語意相同。","textEn":"Mechanical fit does not establish electrical, information or functional equivalence."}],"quiz":{"options":["僅沿用原先的單位標籤","核對接收端解讀、校正與文件","只確認外殼沒有損傷"],"optionsEn":["Simply retain the old unit label","Review receiver interpretation, calibration and documentation","Only inspect the housing for damage"],"answer":1,"question":"新感測器孔位相同但輸出單位不同，最需要什麼？","questionEn":"A new sensor fits mechanically but uses different output units. What is most needed?","explanation":"輸出語意是系統介面的一部分，不能由機械相容取代。","explanationEn":"Output meaning is part of the system interface and is not verified by mechanical fit."}},{"id":"b301-v6-12","sequence":12,"order":4,"sourceIds":["v6-thsr-discovery","v6-thsr-route-safety","v6-thsr-disaster"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b301-v6-11"],"title":"交付高鐵整合證據矩陣","titleEn":"Deliver the high-speed-rail integration matrix","objective":"讓跨專業判斷有一致位置、版本與完成狀態。","objectiveEn":"Give cross-discipline judgments consistent location, version and completion state.","instruction":"將土建、軌道、集電、ATC及災害圖表列成需求—證據矩陣。選一個橋梁沉降情境，追蹤它可能影響哪些介面，註明只屬學習分析。","instructionEn":"Build a requirement–evidence matrix for civil works, track, collection, ATC and hazards. Trace interfaces potentially affected by a bridge-settlement scenario, labeling it as a learning analysis.","observation":"檢查某一系統的正常證據是否被誤用來替其他系統背書。","observationEn":"Check whether normal evidence for one subsystem is being used to certify another.","failure":"只有各專業合格結論，缺乏交界處相容性的證據。","failureEn":"Collecting individual discipline approvals without evidence of compatibility at their interfaces.","check":"每個介面都有來源、適用情境、未解問題及後續責任。","checkEn":"Give each interface a source, applicable scenario, open issue and follow-up responsibility.","knowledge":[{"id":"b301-v6-12-k1","title":"整合驗證","titleEn":"Integration verification","text":"子系統各自符合要求，仍須檢查連接後的共同功能。","textEn":"Individually compliant subsystems still require verification of their connected functions."},{"id":"b301-v6-12-k2","title":"可追溯交付","titleEn":"Traceable handover","text":"共享位置與版本使不同團隊能重建同一項判斷。","textEn":"Shared location and version identifiers allow teams to reconstruct the same judgment."}],"quiz":{"options":["是否可以刪除全部介面測試","是否已證明所有未測情境都合格","相互連接後是否滿足共同功能"],"optionsEn":["Whether every interface test can be removed","Whether all untested scenarios are thereby proven acceptable","Whether their connections meet shared functional requirements"],"answer":2,"question":"五個子系統各自通過單機測試，下一個合理問題是什麼？","questionEn":"Five subsystems pass standalone tests. What is the next reasonable question?","explanation":"整合行為可能不是單機測試的範圍，需另外的對應證據。","explanationEn":"Integrated behavior may lie outside standalone tests and needs evidence of its own."}}],"title":"災害、維護與交付","titleEn":"Hazards, maintenance and handover","description":"把偵測、決策、現地複核與變更管理分成可追溯步驟。","descriptionEn":"Separate detection, decisions, inspection and configuration changes into traceable stages."},{"id":"b301-v16-s1","title":"延遲與制動距離與曲線超高與未平衡加速度","titleEn":"Delay and braking distance & Cant and unbalanced acceleration","description":"本階段聚焦「延遲與制動距離」與「曲線超高與未平衡加速度」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Delay and braking distance\" and \"Cant and unbalanced acceleration\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b301-v16-01","title":"延遲與制動距離：機制與系統路徑","titleEn":"Delay and braking distance: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v6-12"],"objective":"說明「延遲與制動距離」如何影響台灣高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Delay and braking distance” governs forces, deformation, flow or signals in “Taiwan High Speed Rail”, and map the relevant inputs, transfer paths and boundaries.","instruction":"列車在控制命令傳遞與煞車建立期間仍向前行駛，減速段才把動能耗散；因此停車距離包含延遲距離與減速距離。速度平方項說明高速時少量速度誤差會被放大，固定減速度只能作第一輪界限估算。 延遲項與速度成正比，減速項與速度平方成正比；把兩項分開後，才能選擇改善控制延遲或增加有效制動的方案。若存在坡度，應另加沿坡重力，不能只改總距離。 把警報後的列車停車位置與橋梁邊界放在同一里程圖上。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「延遲與制動距離」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A train continues moving while the command propagates and brake force builds. Only the deceleration phase removes kinetic energy, so stopping distance includes both a delay term and a braking term. The squared speed dependence amplifies speed uncertainty; constant deceleration is only an initial bounding approximation. The delay term is linear in speed and the deceleration term is quadratic. Separating them reveals whether control latency or effective braking deserves attention. A gradient requires an added gravitational component, not an arbitrary adjustment to the final distance. Plot the post-alarm stopping position and bridge limits on the same chainage diagram. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Delay and braking distance” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：v=70 m/s; delay=2.5 s; a=0.7 m/s^2；計算：distance=v*delay+v*v/(2*a)=3675 m。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: v=70 m/s; delay=2.5 s; a=0.7 m/s^2; calculation: distance=v*delay+v*v/(2*a)=3675 m.","failure":"常見誤解：「速度增加一成時制動距離必定也只增加一成」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A ten percent speed increase must increase braking distance by only ten percent.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「延遲與制動距離」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Delay and braking distance”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b301-v16-01-k1","title":"延遲與制動距離","titleEn":"Delay and braking distance","text":"列車在控制命令傳遞與煞車建立期間仍向前行駛，減速段才把動能耗散；因此停車距離包含延遲距離與減速距離。速度平方項說明高速時少量速度誤差會被放大，固定減速度只能作第一輪界限估算。","textEn":"A train continues moving while the command propagates and brake force builds. Only the deceleration phase removes kinetic energy, so stopping distance includes both a delay term and a braking term.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：速度增加一成時制動距離必定也只增加一成 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A ten percent speed increase must increase braking distance by only ten percent. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「延遲與制動距離」，下列哪一項敘述正確？","questionEn":"Which statement about \"Delay and braking distance\" is correct?","options":["速度增加一成時制動距離必定也只增加一成","列車在控制命令傳遞與煞車建立期間仍向前行駛，減速段才把動能耗散；因此停車距離包含延遲距離與減速距離。","任何速度下增加超高都一定減少車內橫向加速度"],"optionsEn":["A ten percent speed increase must increase braking distance by only ten percent.","A train continues moving while the command propagates and brake force builds.","Increasing cant always reduces lateral acceleration at every operating speed."],"answer":1,"explanation":"列車在控制命令傳遞與煞車建立期間仍向前行駛，減速段才把動能耗散；因此停車距離包含延遲距離與減速距離。 其餘選項是常見誤解。","explanationEn":"A train continues moving while the command propagates and brake force builds. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":13},{"id":"b301-v16-02","title":"延遲與制動距離：定量估算","titleEn":"Delay and braking distance: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-01"],"objective":"以數值模型估算「延遲與制動距離」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Delay and braking distance” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：v=70 m/s; delay=2.5 s; a=0.7 m/s^2；計算：distance=v*delay+v*v/(2*a)=3675 m。敏感度：v 單獨增加百分之十至 77 m/s，其餘固定，結果為 4427.5 m。模型邊界：水平直線、定減速、無風；沒有建立黏著分布與煞車熱衰退。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: v=70 m/s; delay=2.5 s; a=0.7 m/s^2; calculation: distance=v*delay+v*v/(2*a)=3675 m. Sensitivity: v, increase this input alone by ten percent, to 77 m/s, with all other inputs fixed, gives 4427.5 m. Model boundary: Level straight track and constant deceleration; adhesion variation and thermal fade are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：對齊速度、煞車缸壓力與里程的時間戳，分開辨識命令延遲及穩態減速度，再以積分速度的距離交叉檢查。","observationEn":"How to cross-check: Align speed, brake-cylinder pressure and distance timestamps.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b301-v16-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：v=70 m/s; delay=2.5 s; a=0.7 m/s^2；計算：distance=v*delay+v*v/(2*a)=3675 m。敏感度：v 單獨增加百分之十至 77 m/s，其餘固定，結果為 4427.5 m。模型邊界：水平直線、定減速、無風；沒有建立黏著分布與煞車熱衰退。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: v=70 m/s; delay=2.5 s; a=0.7 m/s^2; calculation: distance=v*delay+v*v/(2*a)=3675 m. Sensitivity: v, increase this input alone by ten percent, to 77 m/s, with all other inputs fixed, gives 4427.5 m. Model boundary: Level straight track and constant deceleration; adhesion variation and thermal fade are excluded.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「延遲與制動距離」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Delay and braking distance\", which statement holds?","options":["地震預警成功觸發就代表列車必能在強震前完全停下","只要靜態接觸線高度正確就能保證高速受流品質","原創假想算例，全部輸入均非本工程操作參數：v=70 m/s; delay=2.5 s; a=0.7 m/s^2。"],"optionsEn":["A successfully triggered earthquake warning guarantees a complete stop before strong shaking.","Correct static contact-wire height alone guarantees good current collection at high speed.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：v=70 m/s; delay=2.5 s; a=0.7 m/s^2；計算：distance=v*delay+v*v/(2*a)=3675 m。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: v=70 m/s; delay=2.5 s; a=0.7 m/s^2; calculation: distance=v*delay+v*v/(2*a)=3675 m. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":14},{"id":"b301-v16-03","title":"延遲與制動距離：試驗與驗證","titleEn":"Delay and braking distance: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「延遲與制動距離」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Delay and braking distance” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"對齊速度、煞車缸壓力與里程的時間戳，分開辨識命令延遲及穩態減速度，再以積分速度的距離交叉檢查。 用獨立里程或地速核對輪速積分，報告濕乾軌差異及停車距離的重複試驗範圍。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Align speed, brake-cylinder pressure and distance timestamps. Identify command delay separately from steady deceleration and cross-check distance by integrating measured speed. Check integrated wheel speed against independent distance or ground speed, and report wet-dry differences and repeated stopping-distance ranges. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：分別增加延遲與初速，畫出兩條停車曲線；寫出哪個區段對各參數敏感，以及需要哪些現場資料才可建立保護曲線。 再以本單元 v 的對照值重算 distance，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Increase delay and initial speed separately, plot both stopping curves, identify the sensitive phase, and list the field evidence needed before defining a protection curve. Also recalculate distance for the alternative v value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：輪滑保護介入與濕軌會降低實際減速度；感測時間不同步也能製造假延遲，須以第二個時鐘和輪速紀錄區分。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Wheel-slide protection and wet rails can reduce deceleration; unsynchronised sensors can imitate a delay, requiring an independent clock and wheel-speed records. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b301-v16-03-k1","title":"驗證方法","titleEn":"Verification method","text":"對齊速度、煞車缸壓力與里程的時間戳，分開辨識命令延遲及穩態減速度，再以積分速度的距離交叉檢查。 用獨立里程或地速核對輪速積分，報告濕乾軌差異及停車距離的重複試驗範圍。","textEn":"Align speed, brake-cylinder pressure and distance timestamps. Identify command delay separately from steady deceleration and cross-check distance by integrating measured speed. Check integrated wheel speed against independent distance or ground speed, and report wet-dry differences and repeated stopping-distance ranges.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-03-k2","title":"現場實務","titleEn":"Site practice","text":"分別增加延遲與初速，畫出兩條停車曲線；寫出哪個區段對各參數敏感，以及需要哪些現場資料才可建立保護曲線。 再以本單元 v 的對照值重算 distance，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Increase delay and initial speed separately, plot both stopping curves, identify the sensitive phase, and list the field evidence needed before defining a protection curve. Also recalculate distance for the alternative v value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「延遲與制動距離」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Delay and braking distance\"?","options":["對齊速度、煞車缸壓力與里程的時間戳，分開辨識命令延遲及穩態減速度，再以積分速度的距離交叉檢查。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","隧道壓力波必定與列車以相同速度到達出口"],"optionsEn":["Align speed, brake-cylinder pressure and distance timestamps.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","A tunnel pressure wave necessarily reaches the portal at the same speed as the train."],"answer":0,"explanation":"對齊速度、煞車缸壓力與里程的時間戳，分開辨識命令延遲及穩態減速度，再以積分速度的距離交叉檢查。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Align speed, brake-cylinder pressure and distance timestamps. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":15},{"id":"b301-v16-04","title":"延遲與制動距離：失效診斷","titleEn":"Delay and braking distance: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-03"],"objective":"從症狀倒推「延遲與制動距離」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Delay and braking distance” and propose discriminating checks, corrective actions and prevention.","instruction":"輪滑保護介入與濕軌會降低實際減速度；感測時間不同步也能製造假延遲，須以第二個時鐘和輪速紀錄區分。 應比較壓力建立與地速下降先後，避免誤判煞車故障。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Wheel-slide protection and wet rails can reduce deceleration; unsynchronised sensors can imitate a delay, requiring an independent clock and wheel-speed records. Compare pressure build-up with ground-speed decay before diagnosing a brake fault. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：把警報後的列車停車位置與橋梁邊界放在同一里程圖上。","observationEn":"Link to the mechanism: Plot the post-alarm stopping position and bridge limits on the same chainage diagram.","failure":"誤判風險：若相信「速度增加一成時制動距離必定也只增加一成」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A ten percent speed increase must increase braking distance by only ten percent.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b301-v16-04-k1","title":"失效模式","titleEn":"Failure mode","text":"輪滑保護介入與濕軌會降低實際減速度；感測時間不同步也能製造假延遲，須以第二個時鐘和輪速紀錄區分。 應比較壓力建立與地速下降先後，避免誤判煞車故障。","textEn":"Wheel-slide protection and wet rails can reduce deceleration; unsynchronised sensors can imitate a delay, requiring an independent clock and wheel-speed records. Compare pressure build-up with ground-speed decay before diagnosing a brake fault.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「延遲與制動距離」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Delay and braking distance\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","輪滑保護介入與濕軌會降低實際減速度；感測時間不同步也能製造假延遲，須以第二個時鐘和輪速紀錄區分。","任何速度下增加超高都一定減少車內橫向加速度"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Wheel-slide protection and wet rails can reduce deceleration.","Increasing cant always reduces lateral acceleration at every operating speed."],"answer":1,"explanation":"輪滑保護介入與濕軌會降低實際減速度；感測時間不同步也能製造假延遲，須以第二個時鐘和輪速紀錄區分。 需以量測區分可能原因。","explanationEn":"Wheel-slide protection and wet rails can reduce deceleration; unsynchronised sensors can imitate a delay, requiring an independent clock and wheel-speed records. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":16},{"id":"b301-v16-05","title":"曲線超高與未平衡加速度：機制與系統路徑","titleEn":"Cant and unbalanced acceleration: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-04"],"objective":"說明「曲線超高與未平衡加速度」如何影響台灣高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Cant and unbalanced acceleration” governs forces, deformation, flow or signals in “Taiwan High Speed Rail”, and map the relevant inputs, transfer paths and boundaries.","instruction":"曲線需求的向心加速度由重力沿軌道平面的分量與輪軌側向作用共同提供。超高平衡速度只對特定半徑和速度成立，慢車可能出現超高過剩；不能把增加超高當成所有車種都受益的措施。 殘餘加速度的正負表示側向作用方向，而不是安全與危險的二元判斷。半徑、軌距與高差必須使用一致長度單位，車體感受還會受到懸吊轉角影響。 比較快車通過與低速受限運轉時相同曲線的殘餘側向加速度。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「曲線超高與未平衡加速度」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"On a curve, the component of gravity in the track plane and wheel-rail lateral forces together provide centripetal acceleration. Equilibrium cant applies to one radius and speed. A slower service can experience cant excess, so increasing cant does not improve every train condition. The sign of residual acceleration identifies its lateral direction, not a binary safe-unsafe outcome. Radius, gauge and rail-level difference require consistent length units. Carbody response is additionally affected by suspension rotation, which this geometric estimate does not resolve. Compare residual lateral acceleration on one curve during fast passage and restricted low-speed operation. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Cant and unbalanced acceleration” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：v=60 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m；計算：residual=v*v/R-9.81*cant/gauge=0.1152 m/s^2。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: v=60 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m; calculation: residual=v*v/R-9.81*cant/gauge=0.1152 m/s^2.","failure":"常見誤解：「任何速度下增加超高都一定減少車內橫向加速度」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Increasing cant always reduces lateral acceleration at every operating speed.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「曲線超高與未平衡加速度」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Cant and unbalanced acceleration”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b301-v16-05-k1","title":"曲線超高與未平衡加速度","titleEn":"Cant and unbalanced acceleration","text":"曲線需求的向心加速度由重力沿軌道平面的分量與輪軌側向作用共同提供。超高平衡速度只對特定半徑和速度成立，慢車可能出現超高過剩；不能把增加超高當成所有車種都受益的措施。","textEn":"On a curve, the component of gravity in the track plane and wheel-rail lateral forces together provide centripetal acceleration. Equilibrium cant applies to one radius and speed.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：任何速度下增加超高都一定減少車內橫向加速度 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Increasing cant always reduces lateral acceleration at every operating speed. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「曲線超高與未平衡加速度」，下列哪一項敘述正確？","questionEn":"Which statement about \"Cant and unbalanced acceleration\" is correct?","options":["任何速度下增加超高都一定減少車內橫向加速度","完全拘束的鋼軌升溫仍會無應力地自由伸長","曲線需求的向心加速度由重力沿軌道平面的分量與輪軌側向作用共同提供。"],"optionsEn":["Increasing cant always reduces lateral acceleration at every operating speed.","A fully restrained rail still expands freely without stress when heated.","On a curve, the component of gravity in the track plane and wheel-rail lateral forces together provide centripetal acceleration."],"answer":2,"explanation":"曲線需求的向心加速度由重力沿軌道平面的分量與輪軌側向作用共同提供。 其餘選項是常見誤解。","explanationEn":"On a curve, the component of gravity in the track plane and wheel-rail lateral forces together provide centripetal acceleration. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":17},{"id":"b301-v16-06","title":"曲線超高與未平衡加速度：定量估算","titleEn":"Cant and unbalanced acceleration: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-05"],"objective":"以數值模型估算「曲線超高與未平衡加速度」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Cant and unbalanced acceleration” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：v=60 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m；計算：residual=v*v/R-9.81*cant/gauge=0.1152 m/s^2。敏感度：v 單獨增加百分之十至 66 m/s，其餘固定，結果為 0.3042 m/s^2。模型邊界：小角度近似與剛性車體；未計懸吊側滾、動態輪重減載和規範允收值。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: v=60 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m; calculation: residual=v*v/R-9.81*cant/gauge=0.1152 m/s^2. Sensitivity: v, increase this input alone by ten percent, to 66 m/s, with all other inputs fixed, gives 0.3042 m/s^2. Model boundary: Small-angle approximation and rigid body; suspension roll, dynamic wheel unloading and acceptance limits are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在相同半徑區段量測軌面高差與橫向加速度，扣除感測器安裝角度，並把車體讀值與軌道平面讀值分開記錄。","observationEn":"How to cross-check: Measure rail level difference and lateral acceleration on the same curve, remove sensor mounting angle, and distinguish carbody readings from track-plane readings.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b301-v16-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：v=60 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m；計算：residual=v*v/R-9.81*cant/gauge=0.1152 m/s^2。敏感度：v 單獨增加百分之十至 66 m/s，其餘固定，結果為 0.3042 m/s^2。模型邊界：小角度近似與剛性車體；未計懸吊側滾、動態輪重減載和規範允收值。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: v=60 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m; calculation: residual=v*v/R-9.81*cant/gauge=0.1152 m/s^2. Sensitivity: v, increase this input alone by ten percent, to 66 m/s, with all other inputs fixed, gives 0.3042 m/s^2. Model boundary: Small-angle approximation and rigid body; suspension roll, dynamic wheel unloading and acceptance limits are excluded.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「曲線超高與未平衡加速度」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Cant and unbalanced acceleration\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：v=60 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m。","橋梁跨長增加一成其彈性撓度最多只增加一成","只要列車裝有再生煞車全部動能都能回到電網"],"optionsEn":["Original hypothetical exercise.","Increasing bridge span by ten percent increases elastic deflection by at most ten percent.","Installing regenerative braking returns all train kinetic energy to the supply network."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：v=60 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m；計算：residual=v*v/R-9.81*cant/gauge=0.1152 m/s^2。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: v=60 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m; calculation: residual=v*v/R-9.81*cant/gauge=0.1152 m/s^2. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":18},{"id":"b301-v16-07","title":"曲線超高與未平衡加速度：試驗與驗證","titleEn":"Cant and unbalanced acceleration: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「曲線超高與未平衡加速度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Cant and unbalanced acceleration” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在相同半徑區段量測軌面高差與橫向加速度，扣除感測器安裝角度，並把車體讀值與軌道平面讀值分開記錄。 用實測半徑和高差重算平衡速度，保留感測器安裝角的校正值及量測不確定度。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure rail level difference and lateral acceleration on the same curve, remove sensor mounting angle, and distinguish carbody readings from track-plane readings. Recalculate equilibrium speed from measured radius and cant, retaining mounting-angle corrections and uncertainty for the acceleration sensor. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：選兩種速度共同計算殘餘加速度，找出符號反轉位置，說明為何混合服務需要速度分布而非單一最高速度。 再以本單元 v 的對照值重算 residual，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Calculate residual acceleration for two speeds, locate its sign reversal, and explain why mixed services require a speed distribution rather than one maximum speed. Also recalculate residual for the alternative v value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：只依高速通過最佳化超高，可能讓慢車或停車承受反向側向力；感測器橫滾又會把重力投影混入振動訊號。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Cant optimised only for fast trains can impose reverse lateral loading on slow or stopped trains; sensor roll also mixes gravity into vibration measurements. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b301-v16-07-k1","title":"驗證方法","titleEn":"Verification method","text":"在相同半徑區段量測軌面高差與橫向加速度，扣除感測器安裝角度，並把車體讀值與軌道平面讀值分開記錄。 用實測半徑和高差重算平衡速度，保留感測器安裝角的校正值及量測不確定度。","textEn":"Measure rail level difference and lateral acceleration on the same curve, remove sensor mounting angle, and distinguish carbody readings from track-plane readings. Recalculate equilibrium speed from measured radius and cant, retaining mounting-angle corrections and uncertainty for the acceleration sensor.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-07-k2","title":"現場實務","titleEn":"Site practice","text":"選兩種速度共同計算殘餘加速度，找出符號反轉位置，說明為何混合服務需要速度分布而非單一最高速度。 再以本單元 v 的對照值重算 residual，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Calculate residual acceleration for two speeds, locate its sign reversal, and explain why mixed services require a speed distribution rather than one maximum speed. Also recalculate residual for the alternative v value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「曲線超高與未平衡加速度」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Cant and unbalanced acceleration\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","在相同半徑區段量測軌面高差與橫向加速度，扣除感測器安裝角度，並把車體讀值與軌道平面讀值分開記錄。","兩端高程相同就能證明兩點之間沒有差異沉陷"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Measure rail level difference and lateral acceleration on the same curve, remove sensor mounting angle, and distinguish carbody readings from track-plane readings.","Equal endpoint elevations prove there is no differential settlement between them."],"answer":1,"explanation":"在相同半徑區段量測軌面高差與橫向加速度，扣除感測器安裝角度，並把車體讀值與軌道平面讀值分開記錄。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure rail level difference and lateral acceleration on the same curve, remove sensor mounting angle, and distinguish carbody readings from track-plane readings. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":19},{"id":"b301-v16-08","title":"曲線超高與未平衡加速度：失效診斷","titleEn":"Cant and unbalanced acceleration: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-07"],"objective":"從症狀倒推「曲線超高與未平衡加速度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Cant and unbalanced acceleration” and propose discriminating checks, corrective actions and prevention.","instruction":"只依高速通過最佳化超高，可能讓慢車或停車承受反向側向力；感測器橫滾又會把重力投影混入振動訊號。 需核對高差符號與曲線方向，防止左右軌互換。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Cant optimised only for fast trains can impose reverse lateral loading on slow or stopped trains; sensor roll also mixes gravity into vibration measurements. Check cant sign against curve direction to prevent swapping the inner and outer rails. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：比較快車通過與低速受限運轉時相同曲線的殘餘側向加速度。","observationEn":"Link to the mechanism: Compare residual lateral acceleration on one curve during fast passage and restricted low-speed operation.","failure":"誤判風險：若相信「任何速度下增加超高都一定減少車內橫向加速度」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Increasing cant always reduces lateral acceleration at every operating speed.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b301-v16-08-k1","title":"失效模式","titleEn":"Failure mode","text":"只依高速通過最佳化超高，可能讓慢車或停車承受反向側向力；感測器橫滾又會把重力投影混入振動訊號。 需核對高差符號與曲線方向，防止左右軌互換。","textEn":"Cant optimised only for fast trains can impose reverse lateral loading on slow or stopped trains; sensor roll also mixes gravity into vibration measurements. Check cant sign against curve direction to prevent swapping the inner and outer rails.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「曲線超高與未平衡加速度」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Cant and unbalanced acceleration\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","完全拘束的鋼軌升溫仍會無應力地自由伸長","只依高速通過最佳化超高，可能讓慢車或停車承受反向側向力；感測器橫滾又會把重力投影混入振動訊號。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","A fully restrained rail still expands freely without stress when heated.","Cant optimised only for fast trains can impose reverse lateral loading on slow or stopped trains; sensor roll also mixes gravity into vibration measurements."],"answer":2,"explanation":"只依高速通過最佳化超高，可能讓慢車或停車承受反向側向力；感測器橫滾又會把重力投影混入振動訊號。 需以量測區分可能原因。","explanationEn":"Cant optimised only for fast trains can impose reverse lateral loading on slow or stopped trains; sensor roll also mixes gravity into vibration measurements. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":20}],"order":4},{"id":"b301-v16-s2","title":"長軌溫升與受限熱應力與地震偵測提前量","titleEn":"Long-rail temperature and restrained stress & Seismic detection lead time","description":"本階段聚焦「長軌溫升與受限熱應力」與「地震偵測提前量」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Long-rail temperature and restrained stress\" and \"Seismic detection lead time\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b301-v16-09","title":"長軌溫升與受限熱應力：機制與系統路徑","titleEn":"Long-rail temperature and restrained stress: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-08"],"objective":"說明「長軌溫升與受限熱應力」如何影響台灣高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Long-rail temperature and restrained stress” governs forces, deformation, flow or signals in “Taiwan High Speed Rail”, and map the relevant inputs, transfer paths and boundaries.","instruction":"自由鋼軌升溫會伸長，完全拘束的理想鋼軌則把熱應變轉成壓應力。鎖定軌溫決定應力零點而空氣溫度不等於鋼軌溫度；實際扣件滑移與軌道側向阻力還會改變穩定問題。 溫差應相對於鋼軌實際無應力狀態，而非任意室溫。完全拘束估算給出軸向應力尺度；當扣件滑移或軌道彎曲出現時，需要位移相容和側向穩定分析。 以高架曝曬段和隧道出口作為不同鋼軌溫度量測位置。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「長軌溫升與受限熱應力」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A free rail expands on heating, while an ideally restrained rail converts thermal strain into compression. Stress-free rail temperature defines the reference and differs from air temperature. Fastener slip and lateral track resistance additionally govern stability, beyond the one-dimensional thermal-stress estimate. Temperature change must reference the rail’s actual stress-free state, not an arbitrary room temperature. Full restraint gives an axial stress scale. Fastener slip or track curvature requires displacement compatibility and lateral stability analysis beyond this expression. Use an exposed viaduct and a tunnel exit as contrasting rail-temperature measurement locations. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Long-rail temperature and restrained stress” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30 K；計算：compression=E*alpha*deltaT=72.45 MPa。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30 K; calculation: compression=E*alpha*deltaT=72.45 MPa.","failure":"常見誤解：「完全拘束的鋼軌升溫仍會無應力地自由伸長」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A fully restrained rail still expands freely without stress when heated.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「長軌溫升與受限熱應力」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Long-rail temperature and restrained stress”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b301-v16-09-k1","title":"長軌溫升與受限熱應力","titleEn":"Long-rail temperature and restrained stress","text":"自由鋼軌升溫會伸長，完全拘束的理想鋼軌則把熱應變轉成壓應力。鎖定軌溫決定應力零點而空氣溫度不等於鋼軌溫度；實際扣件滑移與軌道側向阻力還會改變穩定問題。","textEn":"A free rail expands on heating, while an ideally restrained rail converts thermal strain into compression. Stress-free rail temperature defines the reference and differs from air temperature.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：完全拘束的鋼軌升溫仍會無應力地自由伸長 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A fully restrained rail still expands freely without stress when heated. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「長軌溫升與受限熱應力」，下列哪一項敘述正確？","questionEn":"Which statement about \"Long-rail temperature and restrained stress\" is correct?","options":["自由鋼軌升溫會伸長，完全拘束的理想鋼軌則把熱應變轉成壓應力。","完全拘束的鋼軌升溫仍會無應力地自由伸長","地震預警成功觸發就代表列車必能在強震前完全停下"],"optionsEn":["A free rail expands on heating, while an ideally restrained rail converts thermal strain into compression.","A fully restrained rail still expands freely without stress when heated.","A successfully triggered earthquake warning guarantees a complete stop before strong shaking."],"answer":0,"explanation":"自由鋼軌升溫會伸長，完全拘束的理想鋼軌則把熱應變轉成壓應力。 其餘選項是常見誤解。","explanationEn":"A free rail expands on heating, while an ideally restrained rail converts thermal strain into compression. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":21},{"id":"b301-v16-10","title":"長軌溫升與受限熱應力：定量估算","titleEn":"Long-rail temperature and restrained stress: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-09"],"objective":"以數值模型估算「長軌溫升與受限熱應力」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Long-rail temperature and restrained stress” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30 K；計算：compression=E*alpha*deltaT=72.45 MPa。敏感度：deltaT 單獨增加百分之十至 33 K，其餘固定，結果為 79.695 MPa。模型邊界：完全軸向拘束與線彈性；不計挫曲、初彎、殘留應力及塑性。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30 K; calculation: compression=E*alpha*deltaT=72.45 MPa. Sensitivity: deltaT, increase this input alone by ten percent, to 33 K, with all other inputs fixed, gives 79.695 MPa. Model boundary: Full axial restraint and linear elasticity; buckling, initial curvature, residual stress and plasticity are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。","observationEn":"How to cross-check: Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b301-v16-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30 K；計算：compression=E*alpha*deltaT=72.45 MPa。敏感度：deltaT 單獨增加百分之十至 33 K，其餘固定，結果為 79.695 MPa。模型邊界：完全軸向拘束與線彈性；不計挫曲、初彎、殘留應力及塑性。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30 K; calculation: compression=E*alpha*deltaT=72.45 MPa. Sensitivity: deltaT, increase this input alone by ten percent, to 33 K, with all other inputs fixed, gives 79.695 MPa. Model boundary: Full axial restraint and linear elasticity; buckling, initial curvature, residual stress and plasticity are excluded.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「長軌溫升與受限熱應力」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Long-rail temperature and restrained stress\", which statement holds?","options":["只要靜態接觸線高度正確就能保證高速受流品質","原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30 K。","隧道壓力波必定與列車以相同速度到達出口"],"optionsEn":["Correct static contact-wire height alone guarantees good current collection at high speed.","Original hypothetical exercise.","A tunnel pressure wave necessarily reaches the portal at the same speed as the train."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30 K；計算：compression=E*alpha*deltaT=72.45 MPa。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30 K; calculation: compression=E*alpha*deltaT=72.45 MPa. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":22},{"id":"b301-v16-11","title":"長軌溫升與受限熱應力：試驗與驗證","titleEn":"Long-rail temperature and restrained stress: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「長軌溫升與受限熱應力」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Long-rail temperature and restrained stress” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。 以鋼軌接觸式溫度計校驗遙測值，核對應變零點，並保留日夜循環的升降溫路徑。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour. Calibrate remote readings against a contact rail thermometer, verify strain zero, and retain heating and cooling paths across the daily cycle. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：畫出自由、部分拘束與完全拘束三種邊界，重算熱變形或應力，標明哪些輸入必須由鋼軌溫度及扣件試驗取得。 再以本單元 deltaT 的對照值重算 compression，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Draw free, partial and full restraint boundaries, recalculate expansion or stress, and identify inputs requiring rail-temperature measurements and fastener tests. Also recalculate compression for the alternative deltaT value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Substituting air temperature misstates thermal loading; loose fasteners may reduce local force while increasing displacement, which does not prove improved overall stability. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b301-v16-11-k1","title":"驗證方法","titleEn":"Verification method","text":"量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。 以鋼軌接觸式溫度計校驗遙測值，核對應變零點，並保留日夜循環的升降溫路徑。","textEn":"Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour. Calibrate remote readings against a contact rail thermometer, verify strain zero, and retain heating and cooling paths across the daily cycle.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-11-k2","title":"現場實務","titleEn":"Site practice","text":"畫出自由、部分拘束與完全拘束三種邊界，重算熱變形或應力，標明哪些輸入必須由鋼軌溫度及扣件試驗取得。 再以本單元 deltaT 的對照值重算 compression，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Draw free, partial and full restraint boundaries, recalculate expansion or stress, and identify inputs requiring rail-temperature measurements and fastener tests. Also recalculate compression for the alternative deltaT value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「長軌溫升與受限熱應力」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Long-rail temperature and restrained stress\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","設備可用度高就表示所有安全風險一定很低","量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","High equipment availability necessarily means every safety risk is low.","Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour."],"answer":2,"explanation":"量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":23},{"id":"b301-v16-12","title":"長軌溫升與受限熱應力：失效診斷","titleEn":"Long-rail temperature and restrained stress: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-11"],"objective":"從症狀倒推「長軌溫升與受限熱應力」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Long-rail temperature and restrained stress” and propose discriminating checks, corrective actions and prevention.","instruction":"把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。 需查鎖定軌溫紀錄，不能以當天最低氣溫當無應力點。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Substituting air temperature misstates thermal loading; loose fasteners may reduce local force while increasing displacement, which does not prove improved overall stability. Check stress-free-temperature records rather than using the day’s minimum air temperature as the reference. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：以高架曝曬段和隧道出口作為不同鋼軌溫度量測位置。","observationEn":"Link to the mechanism: Use an exposed viaduct and a tunnel exit as contrasting rail-temperature measurement locations.","failure":"誤判風險：若相信「完全拘束的鋼軌升溫仍會無應力地自由伸長」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A fully restrained rail still expands freely without stress when heated.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b301-v16-12-k1","title":"失效模式","titleEn":"Failure mode","text":"把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。 需查鎖定軌溫紀錄，不能以當天最低氣溫當無應力點。","textEn":"Substituting air temperature misstates thermal loading; loose fasteners may reduce local force while increasing displacement, which does not prove improved overall stability. Check stress-free-temperature records rather than using the day’s minimum air temperature as the reference.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「長軌溫升與受限熱應力」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Long-rail temperature and restrained stress\" shows distress, which diagnosis is most reasonable?","options":["把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","地震預警成功觸發就代表列車必能在強震前完全停下"],"optionsEn":["Substituting air temperature misstates thermal loading.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","A successfully triggered earthquake warning guarantees a complete stop before strong shaking."],"answer":0,"explanation":"把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。 需以量測區分可能原因。","explanationEn":"Substituting air temperature misstates thermal loading; loose fasteners may reduce local force while increasing displacement, which does not prove improved overall stability. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":24},{"id":"b301-v16-13","title":"地震偵測提前量：機制與系統路徑","titleEn":"Seismic detection lead time: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-12"],"objective":"說明「地震偵測提前量」如何影響台灣高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Seismic detection lead time” governs forces, deformation, flow or signals in “Taiwan High Speed Rail”, and map the relevant inputs, transfer paths and boundaries.","instruction":"地震警報的可用提前量來自較快波到達感測點與較慢強震波到達設施之間的差，再扣掉傳輸和判定延遲。距離太近時提前量可能為負，警報並不能讓列車瞬間停止。 此處以相同距離比較兩種波速，屬簡化幾何模型。實際感測站可能不在線路與震源之間；可用時間還包括資料品質檢查及保護命令發送，不能只比較波速。 把預警提前量與列車制動時間連結，辨認近場地震的限制。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「地震偵測提前量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Usable seismic lead time is the difference between faster-wave detection and slower damaging-wave arrival, less communication and decision delay. A nearby source may leave negative lead time. An alarm therefore cannot make a moving train stop instantaneously, even when the detection itself works correctly. The exercise compares two wave speeds over the same distance and therefore uses simplified geometry. A real sensor may not lie between the source and railway. Available time also includes data-quality checks and protection-command delivery, not only wave propagation. Link warning lead time to braking time and identify the limitation of a nearby earthquake. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Seismic detection lead time” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：distance=100000 m; vp=6000 m/s; vs=3500 m/s; latency=2 s；計算：lead=distance/vs-distance/vp-latency=9.904762 s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: distance=100000 m; vp=6000 m/s; vs=3500 m/s; latency=2 s; calculation: lead=distance/vs-distance/vp-latency=9.904762 s.","failure":"常見誤解：「地震預警成功觸發就代表列車必能在強震前完全停下」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A successfully triggered earthquake warning guarantees a complete stop before strong shaking.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「地震偵測提前量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Seismic detection lead time”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b301-v16-13-k1","title":"地震偵測提前量","titleEn":"Seismic detection lead time","text":"地震警報的可用提前量來自較快波到達感測點與較慢強震波到達設施之間的差，再扣掉傳輸和判定延遲。距離太近時提前量可能為負，警報並不能讓列車瞬間停止。","textEn":"Usable seismic lead time is the difference between faster-wave detection and slower damaging-wave arrival, less communication and decision delay. A nearby source may leave negative lead time.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：地震預警成功觸發就代表列車必能在強震前完全停下 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A successfully triggered earthquake warning guarantees a complete stop before strong shaking. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「地震偵測提前量」，下列哪一項敘述正確？","questionEn":"Which statement about \"Seismic detection lead time\" is correct?","options":["地震預警成功觸發就代表列車必能在強震前完全停下","地震警報的可用提前量來自較快波到達感測點與較慢強震波到達設施之間的差，再扣掉傳輸和判定延遲。","橋梁跨長增加一成其彈性撓度最多只增加一成"],"optionsEn":["A successfully triggered earthquake warning guarantees a complete stop before strong shaking.","Usable seismic lead time is the difference between faster-wave detection and slower damaging-wave arrival, less communication and decision delay.","Increasing bridge span by ten percent increases elastic deflection by at most ten percent."],"answer":1,"explanation":"地震警報的可用提前量來自較快波到達感測點與較慢強震波到達設施之間的差，再扣掉傳輸和判定延遲。 其餘選項是常見誤解。","explanationEn":"Usable seismic lead time is the difference between faster-wave detection and slower damaging-wave arrival, less communication and decision delay. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":25},{"id":"b301-v16-14","title":"地震偵測提前量：定量估算","titleEn":"Seismic detection lead time: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-13"],"objective":"以數值模型估算「地震偵測提前量」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Seismic detection lead time” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：distance=100000 m; vp=6000 m/s; vs=3500 m/s; latency=2 s；計算：lead=distance/vs-distance/vp-latency=9.904762 s。敏感度：distance 單獨增加百分之十至 110000 m，其餘固定，結果為 11.09524 s。模型邊界：共線源站幾何與固定波速；不預測震度或實際地震動。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: distance=100000 m; vp=6000 m/s; vs=3500 m/s; latency=2 s; calculation: lead=distance/vs-distance/vp-latency=9.904762 s. Sensitivity: distance, increase this input alone by ten percent, to 110000 m, with all other inputs fixed, gives 11.09524 s. Model boundary: Collinear source-station geometry and constant wave speeds; neither intensity nor actual ground motion is predicted. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用歷史或合成波形重播整條訊號鏈，記錄偵測、判定、通訊及列車接收時間，量出漏警、誤警和延遲分布。","observationEn":"How to cross-check: Replay historical or synthetic waveforms through the complete chain, log detection, decision, communication and train receipt times, and measure missed alarms, false alarms and latency distribution.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b301-v16-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：distance=100000 m; vp=6000 m/s; vs=3500 m/s; latency=2 s；計算：lead=distance/vs-distance/vp-latency=9.904762 s。敏感度：distance 單獨增加百分之十至 110000 m，其餘固定，結果為 11.09524 s。模型邊界：共線源站幾何與固定波速；不預測震度或實際地震動。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: distance=100000 m; vp=6000 m/s; vs=3500 m/s; latency=2 s; calculation: lead=distance/vs-distance/vp-latency=9.904762 s. Sensitivity: distance, increase this input alone by ten percent, to 110000 m, with all other inputs fixed, gives 11.09524 s. Model boundary: Collinear source-station geometry and constant wave speeds; neither intensity nor actual ground motion is predicted.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「地震偵測提前量」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Seismic detection lead time\", which statement holds?","options":["只要列車裝有再生煞車全部動能都能回到電網","兩端高程相同就能證明兩點之間沒有差異沉陷","原創假想算例，全部輸入均非本工程操作參數：distance=100000 m; vp=6000 m/s; vs=3500 m/s; latency=2 s。"],"optionsEn":["Installing regenerative braking returns all train kinetic energy to the supply network.","Equal endpoint elevations prove there is no differential settlement between them.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：distance=100000 m; vp=6000 m/s; vs=3500 m/s; latency=2 s；計算：lead=distance/vs-distance/vp-latency=9.904762 s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: distance=100000 m; vp=6000 m/s; vs=3500 m/s; latency=2 s; calculation: lead=distance/vs-distance/vp-latency=9.904762 s. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":26},{"id":"b301-v16-15","title":"地震偵測提前量：試驗與驗證","titleEn":"Seismic detection lead time: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「地震偵測提前量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Seismic detection lead time” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用歷史或合成波形重播整條訊號鏈，記錄偵測、判定、通訊及列車接收時間，量出漏警、誤警和延遲分布。 以完整訊號重播核對每個時間戳，將總延遲分解成判定、網路與列車端處理。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Replay historical or synthetic waveforms through the complete chain, log detection, decision, communication and train receipt times, and measure missed alarms, false alarms and latency distribution. Use full-chain signal replay to verify every timestamp and separate total delay into decision, network and train-side processing components. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將震源距離縮短並把通訊延遲加倍，計算剩餘提前量；與制動時間比較，提出只在模型範圍內成立的結論。 再以本單元 distance 的對照值重算 lead，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Shorten source distance and double communication delay, calculate remaining lead time, and compare it with braking time without extending the conclusion beyond the model. Also recalculate lead for the alternative distance value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：只驗證感測器觸發而不驗證下游通訊，可能高估提前量；設備共用電源也可能讓兩條名義獨立通道同時失效。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Testing the sensor without downstream communication overestimates lead time; a shared power supply can also defeat nominally independent channels simultaneously. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b301-v16-15-k1","title":"驗證方法","titleEn":"Verification method","text":"用歷史或合成波形重播整條訊號鏈，記錄偵測、判定、通訊及列車接收時間，量出漏警、誤警和延遲分布。 以完整訊號重播核對每個時間戳，將總延遲分解成判定、網路與列車端處理。","textEn":"Replay historical or synthetic waveforms through the complete chain, log detection, decision, communication and train receipt times, and measure missed alarms, false alarms and latency distribution. Use full-chain signal replay to verify every timestamp and separate total delay into decision, network and train-side processing components.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-15-k2","title":"現場實務","titleEn":"Site practice","text":"將震源距離縮短並把通訊延遲加倍，計算剩餘提前量；與制動時間比較，提出只在模型範圍內成立的結論。 再以本單元 distance 的對照值重算 lead，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Shorten source distance and double communication delay, calculate remaining lead time, and compare it with braking time without extending the conclusion beyond the model. Also recalculate lead for the alternative distance value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「地震偵測提前量」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Seismic detection lead time\"?","options":["用歷史或合成波形重播整條訊號鏈，記錄偵測、判定、通訊及列車接收時間，量出漏警、誤警和延遲分布。","不確定度太難估計，報告中只寫最佳值即可。","速度增加一成時制動距離必定也只增加一成"],"optionsEn":["Replay historical or synthetic waveforms through the complete chain, log detection, decision, communication and train receipt times, and measure missed alarms, false alarms and latency distribution.","Uncertainty is too hard to estimate, so the report may state only the best value.","A ten percent speed increase must increase braking distance by only ten percent."],"answer":0,"explanation":"用歷史或合成波形重播整條訊號鏈，記錄偵測、判定、通訊及列車接收時間，量出漏警、誤警和延遲分布。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Replay historical or synthetic waveforms through the complete chain, log detection, decision, communication and train receipt times, and measure missed alarms, false alarms and latency distribution. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":27},{"id":"b301-v16-16","title":"地震偵測提前量：失效診斷","titleEn":"Seismic detection lead time: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-15"],"objective":"從症狀倒推「地震偵測提前量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Seismic detection lead time” and propose discriminating checks, corrective actions and prevention.","instruction":"只驗證感測器觸發而不驗證下游通訊，可能高估提前量；設備共用電源也可能讓兩條名義獨立通道同時失效。 感測成功不等於制動成功，須查列車收到命令後的動作。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Testing the sensor without downstream communication overestimates lead time; a shared power supply can also defeat nominally independent channels simultaneously. Successful detection is not successful braking; inspect the train response after command receipt. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：把預警提前量與列車制動時間連結，辨認近場地震的限制。","observationEn":"Link to the mechanism: Link warning lead time to braking time and identify the limitation of a nearby earthquake.","failure":"誤判風險：若相信「地震預警成功觸發就代表列車必能在強震前完全停下」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A successfully triggered earthquake warning guarantees a complete stop before strong shaking.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b301-v16-16-k1","title":"失效模式","titleEn":"Failure mode","text":"只驗證感測器觸發而不驗證下游通訊，可能高估提前量；設備共用電源也可能讓兩條名義獨立通道同時失效。 感測成功不等於制動成功，須查列車收到命令後的動作。","textEn":"Testing the sensor without downstream communication overestimates lead time; a shared power supply can also defeat nominally independent channels simultaneously. Successful detection is not successful braking; inspect the train response after command receipt.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「地震偵測提前量」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Seismic detection lead time\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","只驗證感測器觸發而不驗證下游通訊，可能高估提前量；設備共用電源也可能讓兩條名義獨立通道同時失效。","橋梁跨長增加一成其彈性撓度最多只增加一成"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Testing the sensor without downstream communication overestimates lead time.","Increasing bridge span by ten percent increases elastic deflection by at most ten percent."],"answer":1,"explanation":"只驗證感測器觸發而不驗證下游通訊，可能高估提前量；設備共用電源也可能讓兩條名義獨立通道同時失效。 需以量測區分可能原因。","explanationEn":"Testing the sensor without downstream communication overestimates lead time; a shared power supply can also defeat nominally independent channels simultaneously. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":28}],"order":5},{"id":"b301-v16-s3","title":"橋梁撓度與跨長敏感度與接觸線張力波速","titleEn":"Bridge deflection and span sensitivity & Contact-wire tension wave speed","description":"本階段聚焦「橋梁撓度與跨長敏感度」與「接觸線張力波速」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Bridge deflection and span sensitivity\" and \"Contact-wire tension wave speed\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b301-v16-17","title":"橋梁撓度與跨長敏感度：機制與系統路徑","titleEn":"Bridge deflection and span sensitivity: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-16"],"objective":"說明「橋梁撓度與跨長敏感度」如何影響台灣高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Bridge deflection and span sensitivity” governs forces, deformation, flow or signals in “Taiwan High Speed Rail”, and map the relevant inputs, transfer paths and boundaries.","instruction":"簡支梁在均布荷載下的撓度對跨長有四次方敏感度，截面慣性矩與材料剛度共同抵抗彎曲。鐵道橋還需要動態與軌道相互作用檢查，靜態梁算例只用來辨認參數量級。 跨長四次方使幾何誤差特別重要，但只有在相同支承、均布荷載及截面條件下才可比較。將毫米轉成公尺後再核對剛度，可避免把量測位移誤差變成材料性能判斷。 在高架跨中區分列車載重撓度與支承位置的共同移動。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「橋梁撓度與跨長敏感度」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"For a simply supported beam under uniform load, deflection scales with the fourth power of span. Section inertia and material stiffness jointly resist bending. A railway bridge also requires dynamic and track-interaction checks; this static beam exercise only reveals parameter magnitudes. Fourth-power span dependence makes geometry important, but comparison requires the same support, uniform-load and section assumptions. Convert millimetres and metres consistently before checking stiffness, so a displacement-unit error does not become a false conclusion about material properties. Separate load-induced midspan deflection from movement shared with the viaduct supports. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Bridge deflection and span sensitivity” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：w=50000 N/m; L=25 m; E=3.5e+10 Pa; I=8 m^4；計算：deflection=5*w*L**4/(384*E*I)*1000=0.9082613 mm。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: w=50000 N/m; L=25 m; E=3.5e+10 Pa; I=8 m^4; calculation: deflection=5*w*L**4/(384*E*I)*1000=0.9082613 mm.","failure":"常見誤解：「橋梁跨長增加一成其彈性撓度最多只增加一成」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Increasing bridge span by ten percent increases elastic deflection by at most ten percent.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「橋梁撓度與跨長敏感度」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Bridge deflection and span sensitivity”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b301-v16-17-k1","title":"橋梁撓度與跨長敏感度","titleEn":"Bridge deflection and span sensitivity","text":"簡支梁在均布荷載下的撓度對跨長有四次方敏感度，截面慣性矩與材料剛度共同抵抗彎曲。鐵道橋還需要動態與軌道相互作用檢查，靜態梁算例只用來辨認參數量級。","textEn":"For a simply supported beam under uniform load, deflection scales with the fourth power of span. Section inertia and material stiffness jointly resist bending.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：橋梁跨長增加一成其彈性撓度最多只增加一成 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Increasing bridge span by ten percent increases elastic deflection by at most ten percent. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「橋梁撓度與跨長敏感度」，下列哪一項敘述正確？","questionEn":"Which statement about \"Bridge deflection and span sensitivity\" is correct?","options":["橋梁跨長增加一成其彈性撓度最多只增加一成","只要靜態接觸線高度正確就能保證高速受流品質","簡支梁在均布荷載下的撓度對跨長有四次方敏感度，截面慣性矩與材料剛度共同抵抗彎曲。"],"optionsEn":["Increasing bridge span by ten percent increases elastic deflection by at most ten percent.","Correct static contact-wire height alone guarantees good current collection at high speed.","For a simply supported beam under uniform load, deflection scales with the fourth power of span."],"answer":2,"explanation":"簡支梁在均布荷載下的撓度對跨長有四次方敏感度，截面慣性矩與材料剛度共同抵抗彎曲。 其餘選項是常見誤解。","explanationEn":"For a simply supported beam under uniform load, deflection scales with the fourth power of span. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":29},{"id":"b301-v16-18","title":"橋梁撓度與跨長敏感度：定量估算","titleEn":"Bridge deflection and span sensitivity: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-17"],"objective":"以數值模型估算「橋梁撓度與跨長敏感度」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Bridge deflection and span sensitivity” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：w=50000 N/m; L=25 m; E=3.5e+10 Pa; I=8 m^4；計算：deflection=5*w*L**4/(384*E*I)*1000=0.9082613 mm。敏感度：L 單獨增加百分之十至 27.5 m，其餘固定，結果為 1.329785 mm。模型邊界：簡支Euler梁、小撓度、靜態均布荷載；不代表列車移動荷載。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: w=50000 N/m; L=25 m; E=3.5e+10 Pa; I=8 m^4; calculation: deflection=5*w*L**4/(384*E*I)*1000=0.9082613 mm. Sensitivity: L, increase this input alone by ten percent, to 27.5 m, with all other inputs fixed, gives 1.329785 mm. Model boundary: Simply supported Euler beam, small deflection and static uniform load; not a moving train-load analysis. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在已知載重位置量測跨中和支點位移，扣除支承沉陷後對照彎矩圖，並用卸載後讀值檢查是否存在殘留變形。","observationEn":"How to cross-check: Measure midspan and support movement under known loading, subtract support settlement, compare with the moment diagram, and inspect residual displacement after unloading.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b301-v16-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：w=50000 N/m; L=25 m; E=3.5e+10 Pa; I=8 m^4；計算：deflection=5*w*L**4/(384*E*I)*1000=0.9082613 mm。敏感度：L 單獨增加百分之十至 27.5 m，其餘固定，結果為 1.329785 mm。模型邊界：簡支Euler梁、小撓度、靜態均布荷載；不代表列車移動荷載。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: w=50000 N/m; L=25 m; E=3.5e+10 Pa; I=8 m^4; calculation: deflection=5*w*L**4/(384*E*I)*1000=0.9082613 mm. Sensitivity: L, increase this input alone by ten percent, to 27.5 m, with all other inputs fixed, gives 1.329785 mm. Model boundary: Simply supported Euler beam, small deflection and static uniform load; not a moving train-load analysis.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「橋梁撓度與跨長敏感度」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Bridge deflection and span sensitivity\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：w=50000 N/m; L=25 m; E=3.5e+10 Pa; I=8 m^4。","隧道壓力波必定與列車以相同速度到達出口","設備可用度高就表示所有安全風險一定很低"],"optionsEn":["Original hypothetical exercise.","A tunnel pressure wave necessarily reaches the portal at the same speed as the train.","High equipment availability necessarily means every safety risk is low."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：w=50000 N/m; L=25 m; E=3.5e+10 Pa; I=8 m^4；計算：deflection=5*w*L**4/(384*E*I)*1000=0.9082613 mm。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: w=50000 N/m; L=25 m; E=3.5e+10 Pa; I=8 m^4; calculation: deflection=5*w*L**4/(384*E*I)*1000=0.9082613 mm. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":30},{"id":"b301-v16-19","title":"橋梁撓度與跨長敏感度：試驗與驗證","titleEn":"Bridge deflection and span sensitivity: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「橋梁撓度與跨長敏感度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Bridge deflection and span sensitivity” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在已知載重位置量測跨中和支點位移，扣除支承沉陷後對照彎矩圖，並用卸載後讀值檢查是否存在殘留變形。 先以已知荷載校對位移計量程與零點，分別記錄載入卸載路徑及支點運動。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure midspan and support movement under known loading, subtract support settlement, compare with the moment diagram, and inspect residual displacement after unloading. Check displacement-sensor range and zero under known loading, recording loading and unloading paths separately from support movement. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：保持截面不變增加跨長，再比較提高慣性矩的補償幅度，說明靜態位移符合預期為何仍不能取代動態驗證。 再以本單元 L 的對照值重算 deflection，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Increase span while keeping the section fixed, calculate the compensating inertia change, and explain why agreement in static deflection cannot replace dynamic verification. Also recalculate deflection for the alternative L value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：支承鬆動或局部開裂可能改變有效剛度，若把所有位移都當成梁彎曲，校準出的彈性模數就會失真。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Loose supports and local cracking alter effective stiffness; interpreting all displacement as beam bending produces a misleading calibrated elastic modulus. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b301-v16-19-k1","title":"驗證方法","titleEn":"Verification method","text":"在已知載重位置量測跨中和支點位移，扣除支承沉陷後對照彎矩圖，並用卸載後讀值檢查是否存在殘留變形。 先以已知荷載校對位移計量程與零點，分別記錄載入卸載路徑及支點運動。","textEn":"Measure midspan and support movement under known loading, subtract support settlement, compare with the moment diagram, and inspect residual displacement after unloading. Check displacement-sensor range and zero under known loading, recording loading and unloading paths separately from support movement.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-19-k2","title":"現場實務","titleEn":"Site practice","text":"保持截面不變增加跨長，再比較提高慣性矩的補償幅度，說明靜態位移符合預期為何仍不能取代動態驗證。 再以本單元 L 的對照值重算 deflection，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Increase span while keeping the section fixed, calculate the compensating inertia change, and explain why agreement in static deflection cannot replace dynamic verification. Also recalculate deflection for the alternative L value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「橋梁撓度與跨長敏感度」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Bridge deflection and span sensitivity\"?","options":["允收準則可以等看到量測數據後再決定。","在已知載重位置量測跨中和支點位移，扣除支承沉陷後對照彎矩圖，並用卸載後讀值檢查是否存在殘留變形。","任何速度下增加超高都一定減少車內橫向加速度"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Measure midspan and support movement under known loading, subtract support settlement, compare with the moment diagram, and inspect residual displacement after unloading.","Increasing cant always reduces lateral acceleration at every operating speed."],"answer":1,"explanation":"在已知載重位置量測跨中和支點位移，扣除支承沉陷後對照彎矩圖，並用卸載後讀值檢查是否存在殘留變形。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure midspan and support movement under known loading, subtract support settlement, compare with the moment diagram, and inspect residual displacement after unloading. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":31},{"id":"b301-v16-20","title":"橋梁撓度與跨長敏感度：失效診斷","titleEn":"Bridge deflection and span sensitivity: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-19"],"objective":"從症狀倒推「橋梁撓度與跨長敏感度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Bridge deflection and span sensitivity” and propose discriminating checks, corrective actions and prevention.","instruction":"支承鬆動或局部開裂可能改變有效剛度，若把所有位移都當成梁彎曲，校準出的彈性模數就會失真。 若卸載後仍有位移，須區分基座滑移與構件殘留變形。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Loose supports and local cracking alter effective stiffness; interpreting all displacement as beam bending produces a misleading calibrated elastic modulus. Residual displacement after unloading requires distinguishing fixture slip from permanent structural deformation. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：在高架跨中區分列車載重撓度與支承位置的共同移動。","observationEn":"Link to the mechanism: Separate load-induced midspan deflection from movement shared with the viaduct supports.","failure":"誤判風險：若相信「橋梁跨長增加一成其彈性撓度最多只增加一成」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Increasing bridge span by ten percent increases elastic deflection by at most ten percent.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b301-v16-20-k1","title":"失效模式","titleEn":"Failure mode","text":"支承鬆動或局部開裂可能改變有效剛度，若把所有位移都當成梁彎曲，校準出的彈性模數就會失真。 若卸載後仍有位移，須區分基座滑移與構件殘留變形。","textEn":"Loose supports and local cracking alter effective stiffness; interpreting all displacement as beam bending produces a misleading calibrated elastic modulus. Residual displacement after unloading requires distinguishing fixture slip from permanent structural deformation.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「橋梁撓度與跨長敏感度」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Bridge deflection and span sensitivity\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","只要靜態接觸線高度正確就能保證高速受流品質","支承鬆動或局部開裂可能改變有效剛度，若把所有位移都當成梁彎曲，校準出的彈性模數就會失真。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","Correct static contact-wire height alone guarantees good current collection at high speed.","Loose supports and local cracking alter effective stiffness; interpreting all displacement as beam bending produces a misleading calibrated elastic modulus."],"answer":2,"explanation":"支承鬆動或局部開裂可能改變有效剛度，若把所有位移都當成梁彎曲，校準出的彈性模數就會失真。 需以量測區分可能原因。","explanationEn":"Loose supports and local cracking alter effective stiffness; interpreting all displacement as beam bending produces a misleading calibrated elastic modulus. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":32},{"id":"b301-v16-21","title":"接觸線張力波速：機制與系統路徑","titleEn":"Contact-wire tension wave speed: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-20"],"objective":"說明「接觸線張力波速」如何影響台灣高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Contact-wire tension wave speed” governs forces, deformation, flow or signals in “Taiwan High Speed Rail”, and map the relevant inputs, transfer paths and boundaries.","instruction":"受電弓擾動會沿接觸線傳播，張力提高使橫波速度上升而線密度增加使波速下降。波速與列車速度的比值提供動態風險線索，但多跨懸掛、吊弦和接觸非線性不能由單根弦模型取代。 線密度決定單位長度的慣性，張力提供恢復作用，因此波速平方與張力成正比。提高張力也改變支承受力；波速裕度只能作篩檢，不能推定接觸力必然均勻。 在橋隧交界檢查接觸線張力與接觸品質的變化。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「接觸線張力波速」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Pantograph disturbances propagate along the contact wire. Greater tension raises transverse wave speed, whereas greater mass per length lowers it. The ratio to train speed offers a dynamic clue, but multispan suspension, droppers and contact nonlinearity cannot be replaced by a single-string model. Linear density represents inertia per unit length and tension supplies restoring force, so squared wave speed scales with tension. Higher tension also changes support loading. A wave-speed margin is a screening measure, not proof of uniform contact force. Examine contact-wire tension and collection quality across the transition between bridge and tunnel. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Contact-wire tension wave speed” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：tension=20000 N; density=1.1 kg/m；計算：wave_speed=(tension/density)**0.5=134.84 m/s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: tension=20000 N; density=1.1 kg/m; calculation: wave_speed=(tension/density)**0.5=134.84 m/s.","failure":"常見誤解：「只要靜態接觸線高度正確就能保證高速受流品質」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Correct static contact-wire height alone guarantees good current collection at high speed.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「接觸線張力波速」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Contact-wire tension wave speed”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b301-v16-21-k1","title":"接觸線張力波速","titleEn":"Contact-wire tension wave speed","text":"受電弓擾動會沿接觸線傳播，張力提高使橫波速度上升而線密度增加使波速下降。波速與列車速度的比值提供動態風險線索，但多跨懸掛、吊弦和接觸非線性不能由單根弦模型取代。","textEn":"Pantograph disturbances propagate along the contact wire. Greater tension raises transverse wave speed, whereas greater mass per length lowers it.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要靜態接觸線高度正確就能保證高速受流品質 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Correct static contact-wire height alone guarantees good current collection at high speed. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「接觸線張力波速」，下列哪一項敘述正確？","questionEn":"Which statement about \"Contact-wire tension wave speed\" is correct?","options":["受電弓擾動會沿接觸線傳播，張力提高使橫波速度上升而線密度增加使波速下降。","只要靜態接觸線高度正確就能保證高速受流品質","只要列車裝有再生煞車全部動能都能回到電網"],"optionsEn":["Pantograph disturbances propagate along the contact wire.","Correct static contact-wire height alone guarantees good current collection at high speed.","Installing regenerative braking returns all train kinetic energy to the supply network."],"answer":0,"explanation":"受電弓擾動會沿接觸線傳播，張力提高使橫波速度上升而線密度增加使波速下降。 其餘選項是常見誤解。","explanationEn":"Pantograph disturbances propagate along the contact wire. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":33},{"id":"b301-v16-22","title":"接觸線張力波速：定量估算","titleEn":"Contact-wire tension wave speed: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-21"],"objective":"以數值模型估算「接觸線張力波速」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Contact-wire tension wave speed” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：tension=20000 N; density=1.1 kg/m；計算：wave_speed=(tension/density)**0.5=134.84 m/s。敏感度：tension 單獨增加百分之十至 22000 N，其餘固定，結果為 141.4214 m/s。模型邊界：無彎曲剛度的均勻張弦；不是受流合格判定或允許車速。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: tension=20000 N; density=1.1 kg/m; calculation: wave_speed=(tension/density)**0.5=134.84 m/s. Sensitivity: tension, increase this input alone by ten percent, to 22000 N, with all other inputs fixed, gives 141.4214 m/s. Model boundary: Uniform tensioned string without bending stiffness; not a current-collection acceptance rule or permitted train speed. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：核對補償裝置行程、線溫與張力紀錄，再量測受電弓接觸力統計及離線事件，辨別平均值正常但峰值異常。","observationEn":"How to cross-check: Check compensation travel, wire temperature and tension, then examine contact-force statistics and loss-of-contact events to distinguish acceptable means from abnormal peaks.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b301-v16-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：tension=20000 N; density=1.1 kg/m；計算：wave_speed=(tension/density)**0.5=134.84 m/s。敏感度：tension 單獨增加百分之十至 22000 N，其餘固定，結果為 141.4214 m/s。模型邊界：無彎曲剛度的均勻張弦；不是受流合格判定或允許車速。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: tension=20000 N; density=1.1 kg/m; calculation: wave_speed=(tension/density)**0.5=134.84 m/s. Sensitivity: tension, increase this input alone by ten percent, to 22000 N, with all other inputs fixed, gives 141.4214 m/s. Model boundary: Uniform tensioned string without bending stiffness; not a current-collection acceptance rule or permitted train speed.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「接觸線張力波速」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Contact-wire tension wave speed\", which statement holds?","options":["兩端高程相同就能證明兩點之間沒有差異沉陷","原創假想算例，全部輸入均非本工程操作參數：tension=20000 N; density=1.1 kg/m。","速度增加一成時制動距離必定也只增加一成"],"optionsEn":["Equal endpoint elevations prove there is no differential settlement between them.","Original hypothetical exercise.","A ten percent speed increase must increase braking distance by only ten percent."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：tension=20000 N; density=1.1 kg/m；計算：wave_speed=(tension/density)**0.5=134.84 m/s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: tension=20000 N; density=1.1 kg/m; calculation: wave_speed=(tension/density)**0.5=134.84 m/s. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":34},{"id":"b301-v16-23","title":"接觸線張力波速：試驗與驗證","titleEn":"Contact-wire tension wave speed: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「接觸線張力波速」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Contact-wire tension wave speed” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"核對補償裝置行程、線溫與張力紀錄，再量測受電弓接觸力統計及離線事件，辨別平均值正常但峰值異常。 核對接觸線張力、單位長度質量及量測位置，並用接觸力和離線事件檢查動態品質。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check compensation travel, wire temperature and tension, then examine contact-force statistics and loss-of-contact events to distinguish acceptable means from abnormal peaks. Verify contact-wire tension, mass per unit length and measurement location, then examine contact force and loss-of-contact events for dynamic quality. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將張力降低一成和線密度增加一成分別計算波速，列出尚需哪些接觸力量測才能討論動態受流品質。 再以本單元 tension 的對照值重算 wave_speed，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Reduce tension and increase wire mass density separately by ten percent, calculate wave speed, and identify the contact-force measurements still needed to assess dynamic collection. Also recalculate wave_speed for the alternative tension value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：補償裝置卡滯會讓溫度變化改變張力，吊弦鬆弛又會改變局部動態剛度；只讀取靜態高度難以辨識。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A sticking tensioning device lets temperature change tension, while slack droppers change local dynamic stiffness; static wire height alone cannot identify either mechanism. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b301-v16-23-k1","title":"驗證方法","titleEn":"Verification method","text":"核對補償裝置行程、線溫與張力紀錄，再量測受電弓接觸力統計及離線事件，辨別平均值正常但峰值異常。 核對接觸線張力、單位長度質量及量測位置，並用接觸力和離線事件檢查動態品質。","textEn":"Check compensation travel, wire temperature and tension, then examine contact-force statistics and loss-of-contact events to distinguish acceptable means from abnormal peaks. Verify contact-wire tension, mass per unit length and measurement location, then examine contact force and loss-of-contact events for dynamic quality.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-23-k2","title":"現場實務","titleEn":"Site practice","text":"將張力降低一成和線密度增加一成分別計算波速，列出尚需哪些接觸力量測才能討論動態受流品質。 再以本單元 tension 的對照值重算 wave_speed，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Reduce tension and increase wire mass density separately by ten percent, calculate wave speed, and identify the contact-force measurements still needed to assess dynamic collection. Also recalculate wave_speed for the alternative tension value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「接觸線張力波速」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Contact-wire tension wave speed\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","完全拘束的鋼軌升溫仍會無應力地自由伸長","核對補償裝置行程、線溫與張力紀錄，再量測受電弓接觸力統計及離線事件，辨別平均值正常但峰值異常。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","A fully restrained rail still expands freely without stress when heated.","Check compensation travel, wire temperature and tension, then examine contact-force statistics and loss-of-contact events to distinguish acceptable means from abnormal peaks."],"answer":2,"explanation":"核對補償裝置行程、線溫與張力紀錄，再量測受電弓接觸力統計及離線事件，辨別平均值正常但峰值異常。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check compensation travel, wire temperature and tension, then examine contact-force statistics and loss-of-contact events to distinguish acceptable means from abnormal peaks. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":35},{"id":"b301-v16-24","title":"接觸線張力波速：失效診斷","titleEn":"Contact-wire tension wave speed: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-23"],"objective":"從症狀倒推「接觸線張力波速」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Contact-wire tension wave speed” and propose discriminating checks, corrective actions and prevention.","instruction":"補償裝置卡滯會讓溫度變化改變張力，吊弦鬆弛又會改變局部動態剛度；只讀取靜態高度難以辨識。 波速符合估算仍可能離線，需查看接觸力的時間歷程。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A sticking tensioning device lets temperature change tension, while slack droppers change local dynamic stiffness; static wire height alone cannot identify either mechanism. Agreement in wave-speed estimates does not rule out contact loss; inspect contact-force histories. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：在橋隧交界檢查接觸線張力與接觸品質的變化。","observationEn":"Link to the mechanism: Examine contact-wire tension and collection quality across the transition between bridge and tunnel.","failure":"誤判風險：若相信「只要靜態接觸線高度正確就能保證高速受流品質」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Correct static contact-wire height alone guarantees good current collection at high speed.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b301-v16-24-k1","title":"失效模式","titleEn":"Failure mode","text":"補償裝置卡滯會讓溫度變化改變張力，吊弦鬆弛又會改變局部動態剛度；只讀取靜態高度難以辨識。 波速符合估算仍可能離線，需查看接觸力的時間歷程。","textEn":"A sticking tensioning device lets temperature change tension, while slack droppers change local dynamic stiffness; static wire height alone cannot identify either mechanism. Agreement in wave-speed estimates does not rule out contact loss; inspect contact-force histories.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「接觸線張力波速」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Contact-wire tension wave speed\" shows distress, which diagnosis is most reasonable?","options":["補償裝置卡滯會讓溫度變化改變張力，吊弦鬆弛又會改變局部動態剛度；只讀取靜態高度難以辨識。","只要結構還沒倒，就代表安全餘裕仍然足夠。","只要列車裝有再生煞車全部動能都能回到電網"],"optionsEn":["A sticking tensioning device lets temperature change tension, while slack droppers change local dynamic stiffness.","As long as the structure is still standing, its safety margin must still be adequate.","Installing regenerative braking returns all train kinetic energy to the supply network."],"answer":0,"explanation":"補償裝置卡滯會讓溫度變化改變張力，吊弦鬆弛又會改變局部動態剛度；只讀取靜態高度難以辨識。 需以量測區分可能原因。","explanationEn":"A sticking tensioning device lets temperature change tension, while slack droppers change local dynamic stiffness; static wire height alone cannot identify either mechanism. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":36}],"order":6},{"id":"b301-v16-s4","title":"再生煞車能量與受電條件與隧道壓力波傳遞","titleEn":"Regenerative energy and receptivity & Tunnel pressure-wave travel","description":"本階段聚焦「再生煞車能量與受電條件」與「隧道壓力波傳遞」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Regenerative energy and receptivity\" and \"Tunnel pressure-wave travel\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b301-v16-25","title":"再生煞車能量與受電條件：機制與系統路徑","titleEn":"Regenerative energy and receptivity: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-24"],"objective":"說明「再生煞車能量與受電條件」如何影響台灣高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Regenerative energy and receptivity” governs forces, deformation, flow or signals in “Taiwan High Speed Rail”, and map the relevant inputs, transfer paths and boundaries.","instruction":"煞車可回收的能量上限來自列車動能，但電網是否能接受能量、逆變器效率與輔助負載會改變實際回送量。把機械可回收量和變電站收到的電量分開，才不會把理想效率當成節電實績。 效率係數應涵蓋已宣告的轉換鏈；若把網路接受率也納入，必須說明觀測時間窗。只從速度差估計可回收量，不能辨認能量流向電網、電阻或輔助設備。 比較同方向追蹤列車與單獨列車對回送電能的接受條件。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「再生煞車能量與受電條件」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Train kinetic energy sets an upper bound on regenerative recovery, but network receptivity, converter efficiency and auxiliary demand determine actual delivery. Separating mechanically recoverable energy from electricity received at a substation prevents ideal efficiency from being reported as measured savings. The efficiency must cover a declared conversion chain. If it includes network receptivity, the observation window must be stated. A speed change alone cannot identify how energy divides among the supply network, braking resistors and auxiliary equipment. Compare network receptivity with a following train and with an isolated train movement. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Regenerative energy and receptivity” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：mass=240000 kg; v=25 m/s; eta=0.65 1；計算：recovered=0.5*mass*v*v*eta/3.6e6=13.54167 kWh。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=240000 kg; v=25 m/s; eta=0.65 1; calculation: recovered=0.5*mass*v*v*eta/3.6e6=13.54167 kWh.","failure":"常見誤解：「只要列車裝有再生煞車全部動能都能回到電網」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Installing regenerative braking returns all train kinetic energy to the supply network.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「再生煞車能量與受電條件」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Regenerative energy and receptivity”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b301-v16-25-k1","title":"再生煞車能量與受電條件","titleEn":"Regenerative energy and receptivity","text":"煞車可回收的能量上限來自列車動能，但電網是否能接受能量、逆變器效率與輔助負載會改變實際回送量。把機械可回收量和變電站收到的電量分開，才不會把理想效率當成節電實績。","textEn":"Train kinetic energy sets an upper bound on regenerative recovery, but network receptivity, converter efficiency and auxiliary demand determine actual delivery. Separating mechanically recoverable energy from electricity received at a substation prevents ideal efficiency from being reported as measured savings.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要列車裝有再生煞車全部動能都能回到電網 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Installing regenerative braking returns all train kinetic energy to the supply network. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「再生煞車能量與受電條件」，下列哪一項敘述正確？","questionEn":"Which statement about \"Regenerative energy and receptivity\" is correct?","options":["只要列車裝有再生煞車全部動能都能回到電網","煞車可回收的能量上限來自列車動能，但電網是否能接受能量、逆變器效率與輔助負載會改變實際回送量。","隧道壓力波必定與列車以相同速度到達出口"],"optionsEn":["Installing regenerative braking returns all train kinetic energy to the supply network.","Train kinetic energy sets an upper bound on regenerative recovery, but network receptivity, converter efficiency and auxiliary demand determine actual delivery.","A tunnel pressure wave necessarily reaches the portal at the same speed as the train."],"answer":1,"explanation":"煞車可回收的能量上限來自列車動能，但電網是否能接受能量、逆變器效率與輔助負載會改變實際回送量。 其餘選項是常見誤解。","explanationEn":"Train kinetic energy sets an upper bound on regenerative recovery, but network receptivity, converter efficiency and auxiliary demand determine actual delivery. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":37},{"id":"b301-v16-26","title":"再生煞車能量與受電條件：定量估算","titleEn":"Regenerative energy and receptivity: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-25"],"objective":"以數值模型估算「再生煞車能量與受電條件」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Regenerative energy and receptivity” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：mass=240000 kg; v=25 m/s; eta=0.65 1；計算：recovered=0.5*mass*v*v*eta/3.6e6=13.54167 kWh。敏感度：mass 單獨增加百分之十至 264000 kg，其餘固定，結果為 14.89583 kWh。模型邊界：一次水平減速、固定總效率；不含阻力及架線電壓限制導致的截斷。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=240000 kg; v=25 m/s; eta=0.65 1; calculation: recovered=0.5*mass*v*v*eta/3.6e6=13.54167 kWh. Sensitivity: mass, increase this input alone by ten percent, to 264000 kg, with all other inputs fixed, gives 14.89583 kWh. Model boundary: One level deceleration with fixed overall efficiency; resistance and voltage-limited curtailment are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：同步積分直流鏈、受電端與制動電阻的功率，對照初末速度；將輔助用電和回送電量用一致符號處理。","observationEn":"How to cross-check: Integrate DC-link, line-side and braking-resistor power synchronously and compare initial and final speeds, treating auxiliary consumption and exported energy with consistent signs.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b301-v16-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：mass=240000 kg; v=25 m/s; eta=0.65 1；計算：recovered=0.5*mass*v*v*eta/3.6e6=13.54167 kWh。敏感度：mass 單獨增加百分之十至 264000 kg，其餘固定，結果為 14.89583 kWh。模型邊界：一次水平減速、固定總效率；不含阻力及架線電壓限制導致的截斷。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=240000 kg; v=25 m/s; eta=0.65 1; calculation: recovered=0.5*mass*v*v*eta/3.6e6=13.54167 kWh. Sensitivity: mass, increase this input alone by ten percent, to 264000 kg, with all other inputs fixed, gives 14.89583 kWh. Model boundary: One level deceleration with fixed overall efficiency; resistance and voltage-limited curtailment are excluded.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「再生煞車能量與受電條件」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Regenerative energy and receptivity\", which statement holds?","options":["設備可用度高就表示所有安全風險一定很低","任何速度下增加超高都一定減少車內橫向加速度","原創假想算例，全部輸入均非本工程操作參數：mass=240000 kg; v=25 m/s; eta=0.65 1。"],"optionsEn":["High equipment availability necessarily means every safety risk is low.","Increasing cant always reduces lateral acceleration at every operating speed.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：mass=240000 kg; v=25 m/s; eta=0.65 1；計算：recovered=0.5*mass*v*v*eta/3.6e6=13.54167 kWh。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=240000 kg; v=25 m/s; eta=0.65 1; calculation: recovered=0.5*mass*v*v*eta/3.6e6=13.54167 kWh. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":38},{"id":"b301-v16-27","title":"再生煞車能量與受電條件：試驗與驗證","titleEn":"Regenerative energy and receptivity: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「再生煞車能量與受電條件」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Regenerative energy and receptivity” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"同步積分直流鏈、受電端與制動電阻的功率，對照初末速度；將輔助用電和回送電量用一致符號處理。 檢查功率計正負方向與積分時間邊界，以能量平衡殘差確認回送量未被重複計入。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Integrate DC-link, line-side and braking-resistor power synchronously and compare initial and final speeds, treating auxiliary consumption and exported energy with consistent signs. Check meter polarity and integration boundaries, then use the energy-balance residual to confirm that exported energy has not been counted twice. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較有受電列車與無受電列車兩種功率時間圖，做能量收支表，提出儲能需求並說明額定能量不等於可接受功率。 再以本單元 mass 的對照值重算 recovered，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare power traces with and without a receptive train, build an energy balance, and size an illustrative storage requirement while distinguishing energy capacity from acceptable power. Also recalculate recovered for the alternative mass value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：鄰車不在受電時再生電壓可能升高而轉入電阻制動；只量逆變器端會高估真正回到供電網的能量。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Without a receptive neighbouring train, voltage can rise and trigger resistor braking; measurement only at the inverter can overstate energy returned to the supply network. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b301-v16-27-k1","title":"驗證方法","titleEn":"Verification method","text":"同步積分直流鏈、受電端與制動電阻的功率，對照初末速度；將輔助用電和回送電量用一致符號處理。 檢查功率計正負方向與積分時間邊界，以能量平衡殘差確認回送量未被重複計入。","textEn":"Integrate DC-link, line-side and braking-resistor power synchronously and compare initial and final speeds, treating auxiliary consumption and exported energy with consistent signs. Check meter polarity and integration boundaries, then use the energy-balance residual to confirm that exported energy has not been counted twice.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-27-k2","title":"現場實務","titleEn":"Site practice","text":"比較有受電列車與無受電列車兩種功率時間圖，做能量收支表，提出儲能需求並說明額定能量不等於可接受功率。 再以本單元 mass 的對照值重算 recovered，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare power traces with and without a receptive train, build an energy balance, and size an illustrative storage requirement while distinguishing energy capacity from acceptable power. Also recalculate recovered for the alternative mass value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「再生煞車能量與受電條件」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Regenerative energy and receptivity\"?","options":["同步積分直流鏈、受電端與制動電阻的功率，對照初末速度；將輔助用電和回送電量用一致符號處理。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","地震預警成功觸發就代表列車必能在強震前完全停下"],"optionsEn":["Integrate DC-link, line-side and braking-resistor power synchronously and compare initial and final speeds, treating auxiliary consumption and exported energy with consistent signs.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","A successfully triggered earthquake warning guarantees a complete stop before strong shaking."],"answer":0,"explanation":"同步積分直流鏈、受電端與制動電阻的功率，對照初末速度；將輔助用電和回送電量用一致符號處理。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Integrate DC-link, line-side and braking-resistor power synchronously and compare initial and final speeds, treating auxiliary consumption and exported energy with consistent signs. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":39},{"id":"b301-v16-28","title":"再生煞車能量與受電條件：失效診斷","titleEn":"Regenerative energy and receptivity: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-27"],"objective":"從症狀倒推「再生煞車能量與受電條件」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Regenerative energy and receptivity” and propose discriminating checks, corrective actions and prevention.","instruction":"鄰車不在受電時再生電壓可能升高而轉入電阻制動；只量逆變器端會高估真正回到供電網的能量。 若回送受限，需查架線電壓及電阻制動記錄。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Without a receptive neighbouring train, voltage can rise and trigger resistor braking; measurement only at the inverter can overstate energy returned to the supply network. When export is curtailed, inspect line-voltage and resistor-braking records together. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：比較同方向追蹤列車與單獨列車對回送電能的接受條件。","observationEn":"Link to the mechanism: Compare network receptivity with a following train and with an isolated train movement.","failure":"誤判風險：若相信「只要列車裝有再生煞車全部動能都能回到電網」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Installing regenerative braking returns all train kinetic energy to the supply network.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b301-v16-28-k1","title":"失效模式","titleEn":"Failure mode","text":"鄰車不在受電時再生電壓可能升高而轉入電阻制動；只量逆變器端會高估真正回到供電網的能量。 若回送受限，需查架線電壓及電阻制動記錄。","textEn":"Without a receptive neighbouring train, voltage can rise and trigger resistor braking; measurement only at the inverter can overstate energy returned to the supply network. When export is curtailed, inspect line-voltage and resistor-braking records together.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「再生煞車能量與受電條件」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Regenerative energy and receptivity\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","鄰車不在受電時再生電壓可能升高而轉入電阻制動；只量逆變器端會高估真正回到供電網的能量。","隧道壓力波必定與列車以相同速度到達出口"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Without a receptive neighbouring train, voltage can rise and trigger resistor braking.","A tunnel pressure wave necessarily reaches the portal at the same speed as the train."],"answer":1,"explanation":"鄰車不在受電時再生電壓可能升高而轉入電阻制動；只量逆變器端會高估真正回到供電網的能量。 需以量測區分可能原因。","explanationEn":"Without a receptive neighbouring train, voltage can rise and trigger resistor braking; measurement only at the inverter can overstate energy returned to the supply network. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":40},{"id":"b301-v16-29","title":"隧道壓力波傳遞：機制與系統路徑","titleEn":"Tunnel pressure-wave travel: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-28"],"objective":"說明「隧道壓力波傳遞」如何影響台灣高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Tunnel pressure-wave travel” governs forces, deformation, flow or signals in “Taiwan High Speed Rail”, and map the relevant inputs, transfer paths and boundaries.","instruction":"列車鼻部入隧道產生壓縮擾動，壓力波以接近音速傳播而不是跟著列車速度前進。入口緩衝設計影響波形上升率，波到達出口的時間與車身到達時間屬不同問題，須分開建立量測觸發。 波傳時間由傳播距離除以聲速決定，與列車走完整段的時間不同。此式只預測到達時序而不預測波幅；洞口形狀、列車頭型和反射決定的壓力變化須用其他流動模型。 在連續隧道與洞口測點之間比較聲波傳播時間和列車通過時間，另列波幅問題。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「隧道壓力波傳遞」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A train nose entering a tunnel creates a compression disturbance whose propagation speed is close to acoustic speed rather than train speed. Entrance treatments affect the rise of the waveform. Wave arrival and train arrival are different events and require separate measurement triggers. Wave travel time is propagation distance divided by sound speed, not the time for the train to traverse the section. This expression predicts arrival timing, not amplitude. Portal geometry, train-nose shape and reflections require additional flow models to predict pressure changes. Compare acoustic travel time with train-passage time between tunnel and portal sensors, treating wave amplitude as a separate problem. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Tunnel pressure-wave travel” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：length=2500 m; sound=340 m/s；計算：travel=length/sound=7.352941 s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: length=2500 m; sound=340 m/s; calculation: travel=length/sound=7.352941 s.","failure":"常見誤解：「隧道壓力波必定與列車以相同速度到達出口」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A tunnel pressure wave necessarily reaches the portal at the same speed as the train.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「隧道壓力波傳遞」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Tunnel pressure-wave travel”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b301-v16-29-k1","title":"隧道壓力波傳遞","titleEn":"Tunnel pressure-wave travel","text":"列車鼻部入隧道產生壓縮擾動，壓力波以接近音速傳播而不是跟著列車速度前進。入口緩衝設計影響波形上升率，波到達出口的時間與車身到達時間屬不同問題，須分開建立量測觸發。","textEn":"A train nose entering a tunnel creates a compression disturbance whose propagation speed is close to acoustic speed rather than train speed. Entrance treatments affect the rise of the waveform.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：隧道壓力波必定與列車以相同速度到達出口 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A tunnel pressure wave necessarily reaches the portal at the same speed as the train. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「隧道壓力波傳遞」，下列哪一項敘述正確？","questionEn":"Which statement about \"Tunnel pressure-wave travel\" is correct?","options":["隧道壓力波必定與列車以相同速度到達出口","兩端高程相同就能證明兩點之間沒有差異沉陷","列車鼻部入隧道產生壓縮擾動，壓力波以接近音速傳播而不是跟著列車速度前進。"],"optionsEn":["A tunnel pressure wave necessarily reaches the portal at the same speed as the train.","Equal endpoint elevations prove there is no differential settlement between them.","A train nose entering a tunnel creates a compression disturbance whose propagation speed is close to acoustic speed rather than train speed."],"answer":2,"explanation":"列車鼻部入隧道產生壓縮擾動，壓力波以接近音速傳播而不是跟著列車速度前進。 其餘選項是常見誤解。","explanationEn":"A train nose entering a tunnel creates a compression disturbance whose propagation speed is close to acoustic speed rather than train speed. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":41},{"id":"b301-v16-30","title":"隧道壓力波傳遞：定量估算","titleEn":"Tunnel pressure-wave travel: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-29"],"objective":"以數值模型估算「隧道壓力波傳遞」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Tunnel pressure-wave travel” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：length=2500 m; sound=340 m/s；計算：travel=length/sound=7.352941 s。敏感度：length 單獨增加百分之十至 2750 m，其餘固定，結果為 8.088235 s。模型邊界：一維線性聲學且音速均勻；不預測波幅、微壓波峰值或反射耗散。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: length=2500 m; sound=340 m/s; calculation: travel=length/sound=7.352941 s. Sensitivity: length, increase this input alone by ten percent, to 2750 m, with all other inputs fixed, gives 8.088235 s. Model boundary: One-dimensional linear acoustics with uniform sound speed; amplitude, micro-pressure-wave peaks and reflection losses are not predicted. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在入口與出口配置同步壓力計，用互相關估計傳遞時間，並用溫度估算音速；列車里程觸發另存一條通道。","observationEn":"How to cross-check: Use synchronised pressure sensors at both portals, estimate travel time by cross-correlation and sound speed from temperature, and retain train-position triggering separately.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b301-v16-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：length=2500 m; sound=340 m/s；計算：travel=length/sound=7.352941 s。敏感度：length 單獨增加百分之十至 2750 m，其餘固定，結果為 8.088235 s。模型邊界：一維線性聲學且音速均勻；不預測波幅、微壓波峰值或反射耗散。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: length=2500 m; sound=340 m/s; calculation: travel=length/sound=7.352941 s. Sensitivity: length, increase this input alone by ten percent, to 2750 m, with all other inputs fixed, gives 8.088235 s. Model boundary: One-dimensional linear acoustics with uniform sound speed; amplitude, micro-pressure-wave peaks and reflection losses are not predicted.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「隧道壓力波傳遞」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Tunnel pressure-wave travel\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：length=2500 m; sound=340 m/s。","速度增加一成時制動距離必定也只增加一成","完全拘束的鋼軌升溫仍會無應力地自由伸長"],"optionsEn":["Original hypothetical exercise.","A ten percent speed increase must increase braking distance by only ten percent.","A fully restrained rail still expands freely without stress when heated."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：length=2500 m; sound=340 m/s；計算：travel=length/sound=7.352941 s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: length=2500 m; sound=340 m/s; calculation: travel=length/sound=7.352941 s. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":42},{"id":"b301-v16-31","title":"隧道壓力波傳遞：試驗與驗證","titleEn":"Tunnel pressure-wave travel: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「隧道壓力波傳遞」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Tunnel pressure-wave travel” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在入口與出口配置同步壓力計，用互相關估計傳遞時間，並用溫度估算音速；列車里程觸發另存一條通道。 在洞口與洞內配置同步壓力測點，對照列車頭部通過時刻，分辨首波與後續反射。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use synchronised pressure sensors at both portals, estimate travel time by cross-correlation and sound speed from temperature, and retain train-position triggering separately. Synchronise pressure sensors at the portal and inside the tunnel with nose-passage time, distinguishing the first wave from later reflections. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較壓力波與列車兩種到達時間，加入一次端部反射畫出事件圖，說明單一延遲量無法判斷出口微壓波是否超標。 再以本單元 length 的對照值重算 travel，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare wave and train arrival times, add one end reflection to the event diagram, and explain why travel time alone cannot establish compliance of portal micro-pressure waves. Also recalculate travel for the alternative length value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：時間戳誤差會被誤認為波速變化；長隧道的反射波與多車事件也可能讓互相關找到錯誤的峰。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Timestamp error can imitate a wave-speed change, while reflected waves and multiple train events can make cross-correlation select the wrong peak. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b301-v16-31-k1","title":"驗證方法","titleEn":"Verification method","text":"在入口與出口配置同步壓力計，用互相關估計傳遞時間，並用溫度估算音速；列車里程觸發另存一條通道。 在洞口與洞內配置同步壓力測點，對照列車頭部通過時刻，分辨首波與後續反射。","textEn":"Use synchronised pressure sensors at both portals, estimate travel time by cross-correlation and sound speed from temperature, and retain train-position triggering separately. Synchronise pressure sensors at the portal and inside the tunnel with nose-passage time, distinguishing the first wave from later reflections.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-31-k2","title":"現場實務","titleEn":"Site practice","text":"比較壓力波與列車兩種到達時間，加入一次端部反射畫出事件圖，說明單一延遲量無法判斷出口微壓波是否超標。 再以本單元 length 的對照值重算 travel，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare wave and train arrival times, add one end reflection to the event diagram, and explain why travel time alone cannot establish compliance of portal micro-pressure waves. Also recalculate travel for the alternative length value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「隧道壓力波傳遞」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Tunnel pressure-wave travel\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","在入口與出口配置同步壓力計，用互相關估計傳遞時間，並用溫度估算音速；列車里程觸發另存一條通道。","橋梁跨長增加一成其彈性撓度最多只增加一成"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Use synchronised pressure sensors at both portals, estimate travel time by cross-correlation and sound speed from temperature, and retain train-position triggering separately.","Increasing bridge span by ten percent increases elastic deflection by at most ten percent."],"answer":1,"explanation":"在入口與出口配置同步壓力計，用互相關估計傳遞時間，並用溫度估算音速；列車里程觸發另存一條通道。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use synchronised pressure sensors at both portals, estimate travel time by cross-correlation and sound speed from temperature, and retain train-position triggering separately. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":43},{"id":"b301-v16-32","title":"隧道壓力波傳遞：失效診斷","titleEn":"Tunnel pressure-wave travel: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-31"],"objective":"從症狀倒推「隧道壓力波傳遞」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Tunnel pressure-wave travel” and propose discriminating checks, corrective actions and prevention.","instruction":"時間戳誤差會被誤認為波速變化；長隧道的反射波與多車事件也可能讓互相關找到錯誤的峰。 單點峰值不足以判別首波，須檢查測點間傳遞時差。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Timestamp error can imitate a wave-speed change, while reflected waves and multiple train events can make cross-correlation select the wrong peak. A single peak cannot identify the first wave; inspect propagation delay between sensors. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：在連續隧道與洞口測點之間比較聲波傳播時間和列車通過時間，另列波幅問題。","observationEn":"Link to the mechanism: Compare acoustic travel time with train-passage time between tunnel and portal sensors, treating wave amplitude as a separate problem.","failure":"誤判風險：若相信「隧道壓力波必定與列車以相同速度到達出口」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A tunnel pressure wave necessarily reaches the portal at the same speed as the train.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b301-v16-32-k1","title":"失效模式","titleEn":"Failure mode","text":"時間戳誤差會被誤認為波速變化；長隧道的反射波與多車事件也可能讓互相關找到錯誤的峰。 單點峰值不足以判別首波，須檢查測點間傳遞時差。","textEn":"Timestamp error can imitate a wave-speed change, while reflected waves and multiple train events can make cross-correlation select the wrong peak. A single peak cannot identify the first wave; inspect propagation delay between sensors.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「隧道壓力波傳遞」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Tunnel pressure-wave travel\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","兩端高程相同就能證明兩點之間沒有差異沉陷","時間戳誤差會被誤認為波速變化；長隧道的反射波與多車事件也可能讓互相關找到錯誤的峰。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Equal endpoint elevations prove there is no differential settlement between them.","Timestamp error can imitate a wave-speed change, while reflected waves and multiple train events can make cross-correlation select the wrong peak."],"answer":2,"explanation":"時間戳誤差會被誤認為波速變化；長隧道的反射波與多車事件也可能讓互相關找到錯誤的峰。 需以量測區分可能原因。","explanationEn":"Timestamp error can imitate a wave-speed change, while reflected waves and multiple train events can make cross-correlation select the wrong peak. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":44}],"order":7},{"id":"b301-v16-s5","title":"沉陷差與軌道坡折與可用度與修復時間","titleEn":"Differential settlement and track kink & Availability and repair time","description":"本階段聚焦「沉陷差與軌道坡折」與「可用度與修復時間」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Differential settlement and track kink\" and \"Availability and repair time\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b301-v16-33","title":"沉陷差與軌道坡折：機制與系統路徑","titleEn":"Differential settlement and track kink: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-32"],"objective":"說明「沉陷差與軌道坡折」如何影響台灣高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Differential settlement and track kink” governs forces, deformation, flow or signals in “Taiwan High Speed Rail”, and map the relevant inputs, transfer paths and boundaries.","instruction":"均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。兩端高差除以基長只給平均坡度，無法描述局部尖峰；需要多點剖面才能辨認曲率與變形長度。 相同端點坡度可以對應完全不同的中間形狀，因此坡度不能單獨表示軌道曲率。測點間距必須小於欲辨認的變形尺度，並將高程誤差相對於基長傳遞到坡度結果。 在橋台與路堤銜接處設計足以辨認短波變形的測點。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「沉陷差與軌道坡折」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading. End-to-end difference divided by baseline gives only an average gradient, not a local peak. A spatial profile is needed to identify curvature and deformation length. Identical endpoint gradient can hide very different intermediate shapes, so gradient alone cannot describe track curvature. Survey spacing must resolve the deformation length scale, and elevation uncertainty must be propagated relative to the baseline into the reported gradient. Place survey points at a bridge-abutment transition densely enough to resolve short deformation wavelengths. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Differential settlement and track kink” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：drop=0.012 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.6 mm/m。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.012 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.6 mm/m.","failure":"常見誤解：「兩端高程相同就能證明兩點之間沒有差異沉陷」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Equal endpoint elevations prove there is no differential settlement between them.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「沉陷差與軌道坡折」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Differential settlement and track kink”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b301-v16-33-k1","title":"沉陷差與軌道坡折","titleEn":"Differential settlement and track kink","text":"均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。兩端高差除以基長只給平均坡度，無法描述局部尖峰；需要多點剖面才能辨認曲率與變形長度。","textEn":"Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading. End-to-end difference divided by baseline gives only an average gradient, not a local peak.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩端高程相同就能證明兩點之間沒有差異沉陷 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Equal endpoint elevations prove there is no differential settlement between them. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「沉陷差與軌道坡折」，下列哪一項敘述正確？","questionEn":"Which statement about \"Differential settlement and track kink\" is correct?","options":["均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。","兩端高程相同就能證明兩點之間沒有差異沉陷","設備可用度高就表示所有安全風險一定很低"],"optionsEn":["Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading.","Equal endpoint elevations prove there is no differential settlement between them.","High equipment availability necessarily means every safety risk is low."],"answer":0,"explanation":"均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。 其餘選項是常見誤解。","explanationEn":"Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":45},{"id":"b301-v16-34","title":"沉陷差與軌道坡折：定量估算","titleEn":"Differential settlement and track kink: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-33"],"objective":"以數值模型估算「沉陷差與軌道坡折」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Differential settlement and track kink” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：drop=0.012 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.6 mm/m。敏感度：drop 單獨增加百分之十至 0.0132 m，其餘固定，結果為 0.66 mm/m。模型邊界：小變形平均坡度；不計車軌耦合動力或容許軌道幾何。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.012 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.6 mm/m. Sensitivity: drop, increase this input alone by ten percent, to 0.0132 m, with all other inputs fixed, gives 0.66 mm/m. Model boundary: Small-deformation average gradient; vehicle-track dynamics and permissible geometry limits are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。","observationEn":"How to cross-check: Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b301-v16-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：drop=0.012 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.6 mm/m。敏感度：drop 單獨增加百分之十至 0.0132 m，其餘固定，結果為 0.66 mm/m。模型邊界：小變形平均坡度；不計車軌耦合動力或容許軌道幾何。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.012 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.6 mm/m. Sensitivity: drop, increase this input alone by ten percent, to 0.0132 m, with all other inputs fixed, gives 0.66 mm/m. Model boundary: Small-deformation average gradient; vehicle-track dynamics and permissible geometry limits are excluded.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「沉陷差與軌道坡折」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Differential settlement and track kink\", which statement holds?","options":["任何速度下增加超高都一定減少車內橫向加速度","原創假想算例，全部輸入均非本工程操作參數：drop=0.012 m; baseline=20 m。","地震預警成功觸發就代表列車必能在強震前完全停下"],"optionsEn":["Increasing cant always reduces lateral acceleration at every operating speed.","Original hypothetical exercise.","A successfully triggered earthquake warning guarantees a complete stop before strong shaking."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：drop=0.012 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.6 mm/m。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.012 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.6 mm/m. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":46},{"id":"b301-v16-35","title":"沉陷差與軌道坡折：試驗與驗證","titleEn":"Differential settlement and track kink: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「沉陷差與軌道坡折」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Differential settlement and track kink” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。 重複觀測同一測點並做閉合檢核，以另一穩定基準核對零點，報告高差與基長各自誤差。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift. Repeat identical points with closure checks, verify zero against another stable reference, and report separate errors for elevation difference and baseline. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：構造端點相同但中間下陷的剖面，與直線坡度模型比較；提出足以辨識沉陷槽寬度的測點間距與複測頻率。 再以本單元 drop 的對照值重算 gradient，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Construct a profile with equal endpoints and an intermediate trough, compare it with a straight-gradient model, and propose spacing and repeat intervals able to resolve the trough. Also recalculate gradient for the alternative drop value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b301-v16-35-k1","title":"驗證方法","titleEn":"Verification method","text":"採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。 重複觀測同一測點並做閉合檢核，以另一穩定基準核對零點，報告高差與基長各自誤差。","textEn":"Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift. Repeat identical points with closure checks, verify zero against another stable reference, and report separate errors for elevation difference and baseline.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-35-k2","title":"現場實務","titleEn":"Site practice","text":"構造端點相同但中間下陷的剖面，與直線坡度模型比較；提出足以辨識沉陷槽寬度的測點間距與複測頻率。 再以本單元 drop 的對照值重算 gradient，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Construct a profile with equal endpoints and an intermediate trough, compare it with a straight-gradient model, and propose spacing and repeat intervals able to resolve the trough. Also recalculate gradient for the alternative drop value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「沉陷差與軌道坡折」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Differential settlement and track kink\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","只要靜態接觸線高度正確就能保證高速受流品質","採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Correct static contact-wire height alone guarantees good current collection at high speed.","Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift."],"answer":2,"explanation":"採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":47},{"id":"b301-v16-36","title":"沉陷差與軌道坡折：失效診斷","titleEn":"Differential settlement and track kink: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-35"],"objective":"從症狀倒推「沉陷差與軌道坡折」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Differential settlement and track kink” and propose discriminating checks, corrective actions and prevention.","instruction":"基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 高差異常需先查基點，不能立刻推定路基局部下沉。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. An unusual level difference requires a datum check before inferring local earthwork settlement. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：在橋台與路堤銜接處設計足以辨認短波變形的測點。","observationEn":"Link to the mechanism: Place survey points at a bridge-abutment transition densely enough to resolve short deformation wavelengths.","failure":"誤判風險：若相信「兩端高程相同就能證明兩點之間沒有差異沉陷」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Equal endpoint elevations prove there is no differential settlement between them.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b301-v16-36-k1","title":"失效模式","titleEn":"Failure mode","text":"基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 高差異常需先查基點，不能立刻推定路基局部下沉。","textEn":"A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. An unusual level difference requires a datum check before inferring local earthwork settlement.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「沉陷差與軌道坡折」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Differential settlement and track kink\" shows distress, which diagnosis is most reasonable?","options":["基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","設備可用度高就表示所有安全風險一定很低"],"optionsEn":["A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","High equipment availability necessarily means every safety risk is low."],"answer":0,"explanation":"基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 需以量測區分可能原因。","explanationEn":"A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":48},{"id":"b301-v16-37","title":"可用度與修復時間：機制與系統路徑","titleEn":"Availability and repair time: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-36"],"objective":"說明「可用度與修復時間」如何影響台灣高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Availability and repair time” governs forces, deformation, flow or signals in “Taiwan High Speed Rail”, and map the relevant inputs, transfer paths and boundaries.","instruction":"在簡化更新過程中，可用度是平均故障間隔占故障間隔加修復時間的比例。這個指標不能替代安全性，因為快速恢復服務可能仍保留危險失效；備品、交通與診斷都會影響實際修復時間。 平均故障間隔和平均修復時間必須使用相同服務邊界；備件等待與到場時間若被排除，數字就不能描述旅客看到的中斷。短期樣本也應報告事件數與觀測時間。 把供電與列車可用性分開，分析停駛時間是否由同一故障主導。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「可用度與修復時間」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"In a simplified renewal process, availability is mean time between failures divided by that time plus mean repair time. It does not replace safety: rapidly restoring service may leave a hazardous failure unresolved. Spares, travel and diagnosis all affect actual restoration time. Mean time between failures and mean repair time require a common service boundary. Excluding spare-part waiting or travel time prevents the figure from describing passenger-visible interruption. Short samples should also report event count and observation duration. Separate power-system and fleet availability to determine whether one failure dominates downtime. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Availability and repair time” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：mtbf=1200 h; mttr=4 h；計算：availability=mtbf/(mtbf+mttr)=0.9966777 1。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: mtbf=1200 h; mttr=4 h; calculation: availability=mtbf/(mtbf+mttr)=0.9966777 1.","failure":"常見誤解：「設備可用度高就表示所有安全風險一定很低」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"High equipment availability necessarily means every safety risk is low.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「可用度與修復時間」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Availability and repair time”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b301-v16-37-k1","title":"可用度與修復時間","titleEn":"Availability and repair time","text":"在簡化更新過程中，可用度是平均故障間隔占故障間隔加修復時間的比例。這個指標不能替代安全性，因為快速恢復服務可能仍保留危險失效；備品、交通與診斷都會影響實際修復時間。","textEn":"In a simplified renewal process, availability is mean time between failures divided by that time plus mean repair time. It does not replace safety: rapidly restoring service may leave a hazardous failure unresolved.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：設備可用度高就表示所有安全風險一定很低 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: High equipment availability necessarily means every safety risk is low. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「可用度與修復時間」，下列哪一項敘述正確？","questionEn":"Which statement about \"Availability and repair time\" is correct?","options":["設備可用度高就表示所有安全風險一定很低","在簡化更新過程中，可用度是平均故障間隔占故障間隔加修復時間的比例。","速度增加一成時制動距離必定也只增加一成"],"optionsEn":["High equipment availability necessarily means every safety risk is low.","In a simplified renewal process, availability is mean time between failures divided by that time plus mean repair time.","A ten percent speed increase must increase braking distance by only ten percent."],"answer":1,"explanation":"在簡化更新過程中，可用度是平均故障間隔占故障間隔加修復時間的比例。 其餘選項是常見誤解。","explanationEn":"In a simplified renewal process, availability is mean time between failures divided by that time plus mean repair time. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":49},{"id":"b301-v16-38","title":"可用度與修復時間：定量估算","titleEn":"Availability and repair time: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-37"],"objective":"以數值模型估算「可用度與修復時間」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Availability and repair time” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：mtbf=1200 h; mttr=4 h；計算：availability=mtbf/(mtbf+mttr)=0.9966777 1。敏感度：mtbf 單獨增加百分之十至 1320 h，其餘固定，結果為 0.9969789 1。模型邊界：兩狀態穩態平均模型；不含計畫維修、共同原因與降級服務品質。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: mtbf=1200 h; mttr=4 h; calculation: availability=mtbf/(mtbf+mttr)=0.9966777 1. Sensitivity: mtbf, increase this input alone by ten percent, to 1320 h, with all other inputs fixed, gives 0.9969789 1. Model boundary: Two-state steady-state mean model; planned maintenance, common causes and degraded service quality are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。","observationEn":"How to cross-check: Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b301-v16-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：mtbf=1200 h; mttr=4 h；計算：availability=mtbf/(mtbf+mttr)=0.9966777 1。敏感度：mtbf 單獨增加百分之十至 1320 h，其餘固定，結果為 0.9969789 1。模型邊界：兩狀態穩態平均模型；不含計畫維修、共同原因與降級服務品質。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mtbf=1200 h; mttr=4 h; calculation: availability=mtbf/(mtbf+mttr)=0.9966777 1. Sensitivity: mtbf, increase this input alone by ten percent, to 1320 h, with all other inputs fixed, gives 0.9969789 1. Model boundary: Two-state steady-state mean model; planned maintenance, common causes and degraded service quality are excluded.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「可用度與修復時間」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Availability and repair time\", which statement holds?","options":["完全拘束的鋼軌升溫仍會無應力地自由伸長","橋梁跨長增加一成其彈性撓度最多只增加一成","原創假想算例，全部輸入均非本工程操作參數：mtbf=1200 h; mttr=4 h。"],"optionsEn":["A fully restrained rail still expands freely without stress when heated.","Increasing bridge span by ten percent increases elastic deflection by at most ten percent.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：mtbf=1200 h; mttr=4 h；計算：availability=mtbf/(mtbf+mttr)=0.9966777 1。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mtbf=1200 h; mttr=4 h; calculation: availability=mtbf/(mtbf+mttr)=0.9966777 1. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":50},{"id":"b301-v16-39","title":"可用度與修復時間：試驗與驗證","titleEn":"Availability and repair time: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「可用度與修復時間」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Availability and repair time” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。 逐項對照故障開始、服務恢復與維修完成時間，公開排除項，並核對總觀測時數。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service. Cross-check fault start, service restoration and repair completion for each event, disclose exclusions, and verify total observed hours. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較提高故障間隔與縮短修復時間兩種措施，用同一故障定義重算，並列出可用度之外需要追蹤的危險失效指標。 再以本單元 mtbf 的對照值重算 availability，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare increasing failure interval with reducing repair time under one failure definition, and list hazardous-failure measures that must be tracked separately from availability. Also recalculate availability for the alternative mtbf value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Shorter replacement time may not improve availability when spare parts remain unavailable; excluding reporting delays can also create an unrepresentative figure. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b301-v16-39-k1","title":"驗證方法","titleEn":"Verification method","text":"將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。 逐項對照故障開始、服務恢復與維修完成時間，公開排除項，並核對總觀測時數。","textEn":"Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service. Cross-check fault start, service restoration and repair completion for each event, disclose exclusions, and verify total observed hours.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-39-k2","title":"現場實務","titleEn":"Site practice","text":"比較提高故障間隔與縮短修復時間兩種措施，用同一故障定義重算，並列出可用度之外需要追蹤的危險失效指標。 再以本單元 mtbf 的對照值重算 availability，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare increasing failure interval with reducing repair time under one failure definition, and list hazardous-failure measures that must be tracked separately from availability. Also recalculate availability for the alternative mtbf value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「可用度與修復時間」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Availability and repair time\"?","options":["將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。","不確定度太難估計，報告中只寫最佳值即可。","只要列車裝有再生煞車全部動能都能回到電網"],"optionsEn":["Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service.","Uncertainty is too hard to estimate, so the report may state only the best value.","Installing regenerative braking returns all train kinetic energy to the supply network."],"answer":0,"explanation":"將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":51},{"id":"b301-v16-40","title":"可用度與修復時間：失效診斷","titleEn":"Availability and repair time: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b301-v16-39"],"objective":"從症狀倒推「可用度與修復時間」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Availability and repair time” and propose discriminating checks, corrective actions and prevention.","instruction":"只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。 修好設備和恢復服務可能不同時，須分別記錄終點。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Shorter replacement time may not improve availability when spare parts remain unavailable; excluding reporting delays can also create an unrepresentative figure. Equipment repair and service restoration may occur at different times; record both endpoints. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：把供電與列車可用性分開，分析停駛時間是否由同一故障主導。","observationEn":"Link to the mechanism: Separate power-system and fleet availability to determine whether one failure dominates downtime.","failure":"誤判風險：若相信「設備可用度高就表示所有安全風險一定很低」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"High equipment availability necessarily means every safety risk is low.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b301-v16-40-k1","title":"失效模式","titleEn":"Failure mode","text":"只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。 修好設備和恢復服務可能不同時，須分別記錄終點。","textEn":"Shorter replacement time may not improve availability when spare parts remain unavailable; excluding reporting delays can also create an unrepresentative figure. Equipment repair and service restoration may occur at different times; record both endpoints.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b301-v16-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b301-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「可用度與修復時間」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Availability and repair time\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。","速度增加一成時制動距離必定也只增加一成"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Shorter replacement time may not improve availability when spare parts remain unavailable.","A ten percent speed increase must increase braking distance by only ten percent."],"answer":1,"explanation":"只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。 需以量測區分可能原因。","explanationEn":"Shorter replacement time may not improve availability when spare parts remain unavailable; excluding reporting delays can also create an unrepresentative figure. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":52}],"order":8}],"title":"台灣高速鐵路","titleEn":"Taiwan High Speed Rail","summary":"以路線、橋隧、軌道、列車與安全控制的介面，理解高速鐵路整合與長期維護。","summaryEn":"Understand high-speed railway integration and maintenance through interfaces among alignment, civil works, track, trains and safety control.","scope":"以公開資料建立的原創教學分解；所有步驟為紙上、數位模型與證據判讀練習。自繪的示意與自設資料必須標示假設；本站未提供現地工程資料，亦不是核准施工、設備操作或水質放行程序。","scopeEn":"Original educational decomposition of public information. Every step is a paper, digital-model or evidence-interpretation exercise. Label assumptions in self-drawn diagrams and invented data; this site does not supply field engineering records or approved construction, operating or water-release procedures.","diagram":{"type":"rail","labels":["土建","軌道","車輛","供電與控制","驗證"],"labelsEn":["Civil works","Track","Rolling stock","Power and control","Verification"],"original":true,"notToScale":true},"stepCount":52,"estimatedMinutes":1240,"curriculumVersion":6,"enrichmentVersion":16,"learningTrack":"rail","learningSubdiscipline":"rail-highspeed","learningTags":["rail","rail-highspeed","rail"],"subcategory":"rail-highspeed","subcategoryTitle":"高速鐵路系統","subcategoryTitleEn":"High-speed rail systems","v16Architecture":{"architectureFamily":"rail-system","architectureNodes":[["路線與土建","Alignment and civil works"],["車輛與接觸","Vehicle and contact"],["牽引供電","Traction supply"],["行車控制","Movement control"],["車站與旅客","Stations and passengers"],["監測與維護","Monitoring and maintenance"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,1],[3,4],[4,5],[5,0],[5,3]]},"v16Extension":{"stages":5,"steps":40,"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"整合原創算例：單元 1 得 distance=3675 m；單元 2 得 residual=0.1152 m/s^2；單元 3 得 compression=72.45 MPa。上述三個結果使用各單元明示的不同邊界，不能任意相加或視為實際工程實測值。以第一單元 v 的擾動測試，結果改為 4427.5 m；學徒需先比較單位、敏感度和假設，再決定是否要細化模型。以臺灣南北高速運輸走廊為背景，設計一段包含高架橋、曲線與隧道的教學路線。比較正常行車、地震警報和異常受電三種工況，要求學徒追蹤每項設計假設如何傳到停車位置與班表恢復。 最終交付應保留原始輸入、測點時間戳、誤差範圍與無法由簡化式證明的結論。","textEn":"Integrated original exercise: unit 1 gives distance=3675 m; unit 2 gives residual=0.1152 m/s^2; unit 3 gives compression=72.45 MPa. These three results use different explicit boundaries and must not be added or presented as measurements of the real railway. Perturbing v in the first unit changes its result to 4427.5 m. Compare units, sensitivity and assumptions before deciding which model needs refinement. Use Taiwan’s north-south high-speed corridor as the setting for an invented alignment with a viaduct, curve and tunnel. Compare routine running, an earthquake warning and disrupted current collection. Trace each design assumption through to stopping position and timetable recovery rather than treating vehicle, structure and control calculations as isolated answers. The final submission should retain original inputs, measurement timestamps, uncertainty ranges and conclusions that the simplified expressions cannot establish.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"focus":"高速鐵路車軌橋與地震系統介面","focusEn":"High speed vehicle track bridge and seismic interfaces"},"flowDiagram":"assets/diagrams/v16-b301-zh.svg","flowDiagramEn":"assets/diagrams/v16-b301-en.svg"}};
